19: function dependentsOf(project: Project, sectionId: string): Set<string> {
20:   const affected = new Set<string>();
21:   let changed = true;
22:   while (changed) {
23:     changed = false;
24:     for (const section of project.sections) {
25:       if (!affected.has(section.id) && section.dependencies.some((id) => id === sectionId || affected.has(id))) {
26:         affected.add(section.id);
27:         changed = true;
28:       }
29:     }
30:   }
31:   return affected;
32: }
