34: /**
35:  * Applies accepted content to a section and invalidates its own approval plus
36:  * every transitive dependent approval. This is the only place a section's
37:  * current draft changes.
38:  */
39: function applySectionContent(project: Project, sectionId: string, content: string, version: number): Project {
40:   const next = clone(project);
41:   const section = next.sections.find((item) => item.id === sectionId);
42:   if (!section) throw new WorkflowConflict(`Unknown section: ${sectionId}`);
43: 
44:   section.content = content;
45:   section.hash = contentHash(content);
46:   section.version = version;
47:   section.status = "DRAFT";
48: 
49:   const affected = dependentsOf(next, sectionId);
50:   for (const dependent of next.sections) {
51:     if (affected.has(dependent.id) && dependent.status === "APPROVED") dependent.status = "STALE";
52:   }
53:   for (const approval of next.approvals) {
54:     if ((approval.sectionId === sectionId || affected.has(approval.sectionId)) && approval.staleReason === null) {
55:       approval.staleReason = `${section.title} changed`;
56:     }
57:   }
58:   return next;
59: }
