65: export function reviseSection(project: Project, sectionId: string, content: string): Project {
66:   const section = project.sections.find((item) => item.id === sectionId);
67:   if (!section) throw new WorkflowConflict(`Unknown section: ${sectionId}`);
68:   if (section.hash === contentHash(content) && section.version > 0) return clone(project);
69:   return projectSchema.parse(refreshNextAction(applySectionContent(project, sectionId, content, section.version + 1)));
