72: /**
73:  * Records an Architect candidate without touching the current draft. A new
74:  * candidate supersedes any earlier pending candidate for the same section.
75:  */
76: export function recordSectionCandidate(
77:   project: Project,
78:   sectionId: string,
79:   input: {
80:     content: string;
81:     summary: string;
82:     requestedChange: string;
83:     sourceOperationId: string | null;
84:   },
85: ): Project {
86:   const next = clone(project);
87:   const section = next.sections.find((item) => item.id === sectionId);
88:   if (!section) throw new WorkflowConflict(`Unknown section: ${sectionId}`);
89:   const content = sanitizeGeneratedMarkdown(input.content);
90:   const validation = validateSectionContent(sectionId, content);
91:   if (!validation.ok) {
92:     throw new SectionContractError(
93:       `The proposed ${section.title} section does not satisfy its content contract: ${validation.errors.join(" ")}`,
94:     );
95:   }
96:   const hash = contentHash(content);
97:   if (hash === section.hash && section.version > 0) {
98:     throw new WorkflowConflict("The proposed revision is identical to the current draft.");
99:   }
100:   const now = new Date().toISOString();
101:   for (const candidate of section.candidateRevisions) {
102:     if (candidate.status === "PENDING") {
103:       candidate.status = "SUPERSEDED";
104:       candidate.decidedAt = now;
105:     }
106:   }
107:   const version = section.version + 1;
108:   section.candidateRevisions.push({
109:     id: randomUUID(),
110:     version,
111:     content,
112:     hash,
113:     status: "PENDING",
114:     sourceOperationId: input.sourceOperationId,
115:     createdAt: now,
116:     baseVersion: section.version,
117:     baseHash: section.hash,
118:     summary: input.summary.slice(0, 4_000),
119:     requestedChange: input.requestedChange.slice(0, 8_000),
120:     decidedAt: null,
121:   });
122:   rememberTranscript(next, "architect", `Prepared proposed revision v${version} for ${section.title}. The current draft is unchanged.`);
123:   return projectSchema.parse(refreshNextAction(next));
124: }
