168: /** Discards a pending candidate. The current draft and approvals are untouched. */
169: export function rejectSectionCandidate(project: Project, sectionId: string, candidateId: string): Project {
170:   const next = clone(project);
171:   const section = next.sections.find((item) => item.id === sectionId);
172:   if (!section) throw new WorkflowConflict(`Unknown section: ${sectionId}`);
173:   const candidate = section.candidateRevisions.find((item) => item.id === candidateId);
174:   if (!candidate) throw new WorkflowConflict("That proposed revision is not in this section.");
175:   if (candidate.status !== "PENDING") throw new WorkflowConflict("Only a pending proposed revision can be discarded.");
176:   candidate.status = "REJECTED";
177:   candidate.decidedAt = new Date().toISOString();
178:   rememberTranscript(next, "system", `Discarded proposed revision v${candidate.version} for ${section.title}. The current draft is unchanged.`);
