182: export function approveSection(project: Project, sectionId: string, version: number, hash: string): Project {
183:   const next = clone(project);
184:   const section = next.sections.find((item) => item.id === sectionId);
185:   if (!section) throw new WorkflowConflict(`Unknown section: ${sectionId}`);
186:   if (next.currentSectionId !== sectionId) throw new WorkflowConflict("Only the current section can be approved.");
187:   if (section.status !== "DRAFT" || section.version !== version || section.hash !== hash) {
188:     throw new WorkflowConflict("Approval does not match the current draft version and hash.");
189:   }
190:   const dependenciesReady = section.dependencies.every((dependency) =>
191:     next.sections.find((item) => item.id === dependency)?.status === "APPROVED",
192:   );
193:   if (!dependenciesReady) throw new WorkflowConflict("Section dependencies are not currently approved.");
194: 
195:   section.status = "APPROVED";
196:   next.approvals.push({
197:     id: randomUUID(),
198:     sectionId,
199:     version,
200:     hash,
201:     approvedAt: new Date().toISOString(),
202:     staleReason: null,
203:   });
204:   return projectSchema.parse(refreshNextAction(next));
205: }
