223: export function recordOracleProposal(
224:   project: Project,
225:   input: {
226:     mode: "questions" | "proposal";
227:     questions: Project["oracleIntake"]["unresolvedQuestions"];
228:     assumptions: Project["oracleIntake"]["assumptions"];
229:     knownConstraints: string[];
230:     intake: {
231:       intendedUser: { value: string; source: "USER" | "ASSUMPTION" | "SYSTEM" } | null;
232:       problem: { value: string; source: "USER" | "ASSUMPTION" | "SYSTEM" } | null;
233:       desiredOutcome: { value: string; source: "USER" | "ASSUMPTION" | "SYSTEM" } | null;
234:       deadlineEvent: { value: string; source: "USER" | "ASSUMPTION" | "SYSTEM" } | null;
235:       mustHaveFeatures: { value: string[]; source: "USER" | "ASSUMPTION" | "SYSTEM" } | null;
236:       optionalFeatures: { value: string[]; source: "USER" | "ASSUMPTION" | "SYSTEM" } | null;
237:       budget: { value: string; source: "USER" | "ASSUMPTION" | "SYSTEM" } | null;
238:       privacyRequirements: { value: string[]; source: "USER" | "ASSUMPTION" | "SYSTEM" } | null;
239:       platforms: { value: string[]; source: "USER" | "ASSUMPTION" | "SYSTEM" } | null;
240:       repositoryCondition: { value: string; source: "USER" | "ASSUMPTION" | "SYSTEM" } | null;
241:       nonGoals: { value: string[]; source: "USER" | "ASSUMPTION" | "SYSTEM" } | null;
242:     };
243:     proposal: NonNullable<Project["product"]["structuredProposal"]> | null;
244:     unresolvedRisks: string[];
245:     recommendedNextAction: string;
246:     sessionId: string;
247:   },
248: ): Project {
249:   const next = clone(project);
250:   const now = new Date().toISOString();
251:   const scalarFields = ["intendedUser", "problem", "desiredOutcome", "deadlineEvent", "budget", "repositoryCondition"] as const;
252:   const listFields = ["mustHaveFeatures", "optionalFeatures", "privacyRequirements", "platforms", "nonGoals"] as const;
253:   for (const field of scalarFields) {
254:     const answer = input.intake[field];
255:     if (!answer) continue;
256:     next.oracleIntake[field] = { ...answer, updatedAt: now };
257:     if (answer.source !== "ASSUMPTION") rememberAnswer(next, field, answer.value, answer.source, input.sessionId, now);
258:   }
259:   for (const field of listFields) {
260:     const answer = input.intake[field];
261:     if (!answer) continue;
262:     next.oracleIntake[field] = { ...answer, updatedAt: now };
263:     if (answer.source !== "ASSUMPTION") rememberAnswer(next, field, answer.value.join("; "), answer.source, input.sessionId, now);
264:   }
265:   next.oracleIntake.status = input.mode === "proposal" ? "READY" : "COLLECTING";
266:   next.oracleIntake.unresolvedQuestions = input.questions;
267:   next.oracleIntake.assumptions = input.assumptions;
268:   next.oracleIntake.knownConstraints = input.knownConstraints;
269:   next.oracleIntake.unresolvedRisks = input.unresolvedRisks;
270:   next.oracleIntake.recommendedNextAction = input.recommendedNextAction;
271:   next.oracleIntake.updatedAt = now;
272: 
273:   syncAssumptionMemory(next, input.assumptions, input.sessionId, now);
274:   syncTextMemory(next, "constraints", input.knownConstraints, "oracle", input.sessionId, now);
275:   syncTextMemory(next, "risks", input.unresolvedRisks, "oracle", input.sessionId, now);
276: 
277:   if (input.mode === "proposal" && input.proposal) {
278:     next.product = {
279:       status: "PROPOSED",
280:       proposal: formatOracleProposal(input.proposal),
281:       structuredProposal: input.proposal,
282:       openQuestions: input.questions.map((question) => question.prompt),
283:     };
284:     syncTextMemory(next, "facts", input.proposal.facts, "oracle", input.sessionId, now);
285:     syncTextMemory(next, "decisions", input.proposal.userDecisions, "user", input.sessionId, now);
286:   } else {
287:     next.product = { status: "NONE", proposal: null, structuredProposal: null, openQuestions: input.questions.map((question) => question.prompt) };
288:   }
289:   rememberSession(next, "oracle", input.sessionId);
290:   rememberTranscript(next, "oracle", input.mode === "proposal"
291:     ? `Prepared a structured proposal: ${input.proposal?.title ?? "Untitled proposal"}. ${input.recommendedNextAction}`
292:     : `Asked ${input.questions.length} focused discovery question(s). ${input.recommendedNextAction}`);
293:   return projectSchema.parse(refreshNextAction(next));
294: }
