357: function syncTextMemory(
358:   project: Project,
359:   bucketName: "facts" | "decisions" | "constraints" | "risks",
360:   texts: string[],
361:   source: "user" | "oracle",
362:   sourceId: string,
363:   createdAt: string,
364: ): void {
365:   const bucket = project.memory[bucketName];
366:   const managedSourceId = `oracle:${sourceId}`;
367:   const current = new Set(texts);
368:   for (const entry of bucket) {
369:     if (entry.sourceId?.startsWith("oracle:") && entry.status !== "SUPERSEDED" && !current.has(entry.text)) {
370:       entry.status = "SUPERSEDED";
371:     }
372:   }
373:   for (const text of texts) {
374:     if (bucket.some((entry) => entry.text === text && entry.status !== "SUPERSEDED")) continue;
375:     const prior = bucket.findLast((entry) => entry.text === text) ?? null;
376:     bucket.push({ id: randomUUID(), text, source, sourceId: managedSourceId, createdAt, field: null, status: "ACTIVE", supersedesId: prior?.id ?? null });
377:   }
378: }
