380: function formatOracleProposal(proposal: NonNullable<Project["product"]["structuredProposal"]>): string {
381:   return [
382:     proposal.summary,
383:     `Intended user: ${proposal.intendedUser}`,
384:     `Problem: ${proposal.problem}`,
385:     `Desired outcome: ${proposal.desiredOutcome}`,
386:     `Must have: ${proposal.mustHaveFeatures.join("; ")}`,
387:     proposal.optionalFeatures.length ? `Optional: ${proposal.optionalFeatures.join("; ")}` : null,
388:     proposal.nonGoals.length ? `Non-goals: ${proposal.nonGoals.join("; ")}` : null,
389:   ].filter(Boolean).join("\n\n");
390: }
