392: export function approveProduct(project: Project): Project {
393:   const next = clone(project);
394:   if (next.product.status !== "PROPOSED" || !next.product.proposal) {
395:     throw new WorkflowConflict("Approve the current Oracle proposal before planning begins.");
396:   }
397:   next.product.status = "APPROVED";
398:   next.oracleIntake.status = "APPROVED";
399:   next.oracleIntake.updatedAt = new Date().toISOString();
400:   rememberTranscript(next, "user", "Approved the Oracle proposal.");
401:   return projectSchema.parse(refreshNextAction(next));
402: }
