404: export function grantMakerScope(project: Project, statement: string): Project {
405:   const next = clone(project);
406:   const unresolved = next.sections.filter((section) => section.status !== "APPROVED");
407:   if (unresolved.length) throw new WorkflowConflict("Maker scope waits until every current section is approved.");
408:   if (next.product.status !== "APPROVED") throw new WorkflowConflict("Maker scope waits for an approved product.");
409:   next.makerScope = { status: "GRANTED", statement };
410:   rememberTranscript(next, "user", `Granted Maker scope: ${statement}`);
411:   return projectSchema.parse(refreshNextAction(next));
412: }
