414: export function recordWitnessDrafts(
415:   project: Project,
416:   drafts: Array<{ title: string; content: string }>,
417:   sessionId: string,
418: ): Project {
419:   const next = clone(project);
420:   next.witnessDrafts = drafts.map((draft) => ({
421:     id: randomUUID(),
422:     title: draft.title,
423:     content: draft.content,
424:     nativeSessionId: sessionId,
425:     createdAt: new Date().toISOString(),
426:   }));
427:   rememberSession(next, "witness", sessionId);
428:   rememberTranscript(next, "witness", drafts.map((draft) => draft.title).join(", "));
429:   return projectSchema.parse(refreshNextAction(next));
430: }
