433: export function compileApprovedPlan(project: Project): string {
434:   const unresolved = project.sections.filter((section) => section.status !== "APPROVED");
435:   if (unresolved.length) throw new WorkflowConflict(`Plan has ${unresolved.length} unresolved section(s).`);
436:   return project.sections
437:     .toSorted((left, right) => left.order - right.order)
438:     .map((section) => `## ${section.title}\n\n${section.content}`)
439:     .join("\n\n");
440: }

