126: /**
127:  * Accepts a pending candidate. This is deliberately separate from approval:
128:  * the section becomes a DRAFT at the candidate version and still needs an
129:  * exact-version approval.
130:  */
131: export function acceptSectionCandidate(project: Project, sectionId: string, candidateId: string): Project {
132:   const next = clone(project);
133:   const section = next.sections.find((item) => item.id === sectionId);
134:   if (!section) throw new WorkflowConflict(`Unknown section: ${sectionId}`);
135:   const candidate = section.candidateRevisions.find((item) => item.id === candidateId);
136:   if (!candidate) throw new WorkflowConflict("That proposed revision is not in this section.");
137:   if (candidate.status !== "PENDING") throw new WorkflowConflict("Only a pending proposed revision can be accepted.");
138:   if (section.version !== candidate.baseVersion || section.hash !== candidate.baseHash) {
139:     throw new WorkflowConflict("The section changed after this candidate was generated. Request a new revision.");
140:   }
141:   const validation = validateSectionContent(sectionId, candidate.content);
142:   if (!validation.ok) {
143:     throw new SectionContractError(
144:       `The proposed ${section.title} section no longer satisfies its content contract: ${validation.errors.join(" ")}`,
145:     );
146:   }
147:   const now = new Date().toISOString();
148:   const applied = applySectionContent(next, sectionId, candidate.content, candidate.version);
149:   const accepted = applied.sections.find((item) => item.id === sectionId);
150:   const acceptedCandidate = accepted?.candidateRevisions.find((item) => item.id === candidateId);
151:   if (!accepted || !acceptedCandidate) throw new WorkflowConflict("The proposed revision could not be applied.");
152:   acceptedCandidate.status = "ACCEPTED";
153:   acceptedCandidate.decidedAt = now;
154:   for (const other of accepted.candidateRevisions) {
155:     if (other.id !== candidateId && other.status === "PENDING") {
156:       other.status = "SUPERSEDED";
157:       other.decidedAt = now;
158:     }
159:   }
160:   rememberTranscript(
161:     applied,
162:     "system",
163:     `Accepted proposed revision v${candidate.version} for ${section.title}. The section is a draft and still needs separate approval.`,
164:   );
165:   return projectSchema.parse(refreshNextAction(applied));
166: }
