296: function rememberAnswer(
297:   project: Project,
298:   field: NonNullable<Project["memory"]["answers"]>[number]["field"],
299:   text: string,
300:   answerSource: "USER" | "ASSUMPTION" | "SYSTEM",
301:   sourceId: string,
302:   createdAt: string,
303: ): void {
304:   const bucket = answerSource === "ASSUMPTION" ? (project.memory.assumptions ??= []) : (project.memory.answers ??= []);
305:   const other = answerSource === "ASSUMPTION" ? (project.memory.answers ??= []) : (project.memory.assumptions ??= []);
306:   const entries = [...bucket, ...other];
307:   const source = answerSource === "USER" ? "user" : answerSource === "SYSTEM" ? "system" : "oracle";
308:   const active = entries.findLast((entry) => entry.field === field && entry.status !== "SUPERSEDED") ?? null;
309:   if (active?.text === text && active.source === source) return;
310:   for (const entry of entries) {
311:     if (entry.field === field && entry.status !== "SUPERSEDED") entry.status = "SUPERSEDED";
312:   }
313:   const prior = active ?? entries.findLast((entry) => entry.field === field) ?? null;
314:   bucket.push({
315:     id: randomUUID(),
316:     text,
317:     source,
318:     sourceId,
319:     createdAt,
320:     field,
321:     status: "ACTIVE",
322:     supersedesId: prior?.id ?? null,
323:   });
324: }
325: 
326: function syncAssumptionMemory(
327:   project: Project,
328:   assumptions: Project["oracleIntake"]["assumptions"],
329:   sourceId: string,
330:   createdAt: string,
331: ): void {
332:   const activeIds = new Set(assumptions.map((assumption) => assumption.id));
333:   const bucket = project.memory.assumptions ??= [];
334:   for (const entry of bucket) {
335:     if (entry.sourceId?.startsWith("assumption:") && !activeIds.has(entry.sourceId.slice("assumption:".length))) {
336:       entry.status = "SUPERSEDED";
337:     }
338:   }
339:   for (const assumption of assumptions) {
340:     const existing = bucket.find((entry) => entry.sourceId === `assumption:${assumption.id}` && entry.status !== "SUPERSEDED");
341:     if (existing?.text === assumption.statement) continue;
342:     if (existing) existing.status = "SUPERSEDED";
343:     bucket.push({
344:       id: randomUUID(),
345:       text: assumption.statement,
346:       source: "oracle",
347:       sourceId: `assumption:${assumption.id}`,
348:       createdAt,
349:       field: assumption.field,
350:       status: "ACTIVE",
351:       supersedesId: existing?.id ?? null,
352:     });
353:   }
354:   void sourceId;
355: }
