262:   /** Retries a Maker run whose previous attempt failed with a confirmed outcome. */
263:   async retryRun(actionId: string, expectedRevision: number, operationId: string) {
264:     const project = await this.workflow.get();
265:     const operation = project.operations.find((item) => item.id === operationId);
266:     if (!operation) throw new WorkflowConflict("That operation is not in this project.");
267:     if (operation.kind !== "maker" || operation.status !== "FAILED") {
268:       throw new ExperienceFailure(
269:         "Retry after failure is available for a Maker run with a confirmed FAILED outcome. Uncertain runs must be reconciled first.",
270:         "RETRY_NOT_CONFIRMED",
271:         409,
272:         false,
273:         operationId,
274:       );
275:     }
276:     if (this.runs.active(operationId)) {
277:       throw new ExperienceFailure("That run is still active. Cancel it instead of retrying.", "RUN_STILL_ACTIVE", 409, false, operationId);
278:     }
279:     return this.runMaker(actionId, expectedRevision, operationId);
280:   }
