282:   /** Marks a still-outstanding operation abandoned after the user confirms. */
283:   async abandonRun(actionId: string, expectedRevision: number, operationId: string) {
284:     const payload = { operationId, intent: "mark-abandoned" };
285:     const claimed = await this.claim(actionId, payload, expectedRevision);
286:     if (claimed.duplicate) return { project: claimed.project, duplicate: true };
287:     if (this.runs.active(operationId) || this.guides.active(operationId)) {
288:       throw new ExperienceFailure("An active in-process run must be cancelled instead of abandoned.", "RUN_STILL_ACTIVE", 409, false, operationId);
289:     }
290:     return this.workflow.execute(actionId, payload, expectedRevision, (project) => {
291:       const next = structuredClone(project);
292:       const operation = next.operations.find((item) => item.id === operationId);
293:       if (!operation) throw new WorkflowConflict("That operation is not in this project.");
294:       if (["SUCCEEDED", "FAILED", "CANCELLED", "ABANDONED"].includes(operation.status)) {
295:         throw new WorkflowConflict("A finished or already abandoned operation cannot be marked abandoned again.");
296:       }
297:       operation.status = "ABANDONED";
298:       operation.statusReason = "user-marked-abandoned";
299:       operation.finishedAt = new Date().toISOString();
300:       operation.lastObservedAt = operation.finishedAt;
301:       operation.result = `${operation.result ?? "The native run is outstanding."} Marked abandoned without a confirmed outcome; reconcile the native session if work must be recovered later.`;
302:       operation.progress = null;
303:       rememberTranscript(next, "system", operation.result);
304:       return refreshNextAction(next);
305:     });
306:   }
