308:   async cancel(actionId: string, expectedRevision: number, operationId: string) {
309:     void expectedRevision;
310:     const active = this.runs.active(operationId) ?? this.guides.active(operationId);
311:     if (!active) {
312:       const project = (await this.store.load()).state;
313:       const operation = project.operations.find((item) => item.id === operationId);
314:       if (!operation) throw new WorkflowConflict("That operation is not in this project.");
315:       if (["SUCCEEDED", "FAILED", "CANCELLED", "COMPLETED_UNAPPLIED", "ABANDONED"].includes(operation.status)) {
316:         throw new WorkflowConflict("A finished or abandoned operation cannot be cancelled. Reconcile an abandoned operation instead.");
317:       }
318:       throw new ExperienceFailure("The in-process runner is no longer present. Reconcile the native session before taking another action.", "RUN_NOT_ACTIVE", 409, false, operationId);
319:     }
320:     let interrupted = false;
321:     const project = (await this.store.load()).state;
322:     const operation = project.operations.find((item) => item.id === operationId);
323:     if (active.sessionId && this.guide.interrupt) {
324:       try {
325:         interrupted = await this.guide.interrupt(active.sessionId);
326:       } catch (error) {
327:         throw new ExperienceFailure(
328:           `The native session could not be interrupted, so it was not marked cancelled: ${this.redact(error instanceof Error ? error.message : "unknown error")}`,
329:           "CANCEL_UNAVAILABLE",
330:           503,
331:           false,
332:           operationId,
333:         );
334:       }
335:     }
336:     if (operation?.kind === "maker") this.runs.markCancelled(operationId);
337:     else this.guides.markCancelled(operationId);
338:     return this.workflow.executeLatest(actionId, { operationId, intent: "cancel" }, (project) => {
339:       const next = structuredClone(project);
340:       const operation = next.operations.find((item) => item.id === operationId);
341:       if (!operation) throw new WorkflowConflict("That operation is not in this project.");
342:       if (["SUCCEEDED", "FAILED", "CANCELLED"].includes(operation.status)) {
343:         if (operation.status === "CANCELLED") return next;
344:         throw new WorkflowConflict("A finished operation cannot be cancelled.");
345:       }
346:       operation.status = "CANCELLED";
347:       operation.finishedAt = new Date().toISOString();
348:       operation.lastObservedAt = operation.finishedAt;
349:       operation.statusReason = "user-cancelled";
350:       operation.progress = null;
351:       operation.result = interrupted
352:         ? "Interrupted the native OpenCode session; the run was cancelled."
353:         : "Cancellation recorded. The native session was already idle or did not report an active request.";
354:       rememberTranscript(next, "system", operation.result);
355:       return refreshNextAction(next);
356:     });
357:   }
