560:   private async queueGuide(
561:     actionId: string,
562:     payload: object,
563:     expectedRevision: number,
564:     intent: "clarify" | "draft" | "witness",
565:     text: string,
566:     project: Project,
567:     proceedWithAssumptions: boolean,
568:     requestedSectionId: string | null,
569:   ) {
570:     if (intent === "clarify" && project.product.status === "APPROVED") {
571:       throw new ExperienceFailure("The product proposal is already approved.", "PRODUCT_ALREADY_APPROVED", 409, false);
572:     }
573:     if (intent === "clarify" && project.source.status !== "CONFIRMED") {
574:       throw new ExperienceFailure(
575:         project.source.status === "PENDING_CONFIRMATION"
576:           ? "Confirm the managed remote workspace before starting Oracle discovery."
577:           : "Choose a project source before starting Oracle discovery.",
578:         "PROJECT_SOURCE_REQUIRED",
579:         409,
580:         false,
581:       );
582:     }
583:     const targetSection = intent === "draft"
584:       ? project.sections.find((section) => section.id === (requestedSectionId ?? project.currentSectionId)) ?? null
585:       : null;
586:     if (intent === "draft" && (project.product.status !== "APPROVED" || !targetSection)) {
587:       throw new ExperienceFailure("Drafting waits for an approved product and a known section.", "SECTION_NOT_READY", 409, false);
588:     }
589:     if (intent === "witness") {
590:       const makerDone = project.operations.some((operation) => operation.kind === "maker" && operation.status === "SUCCEEDED");
591:       if (!makerDone) throw new ExperienceFailure("Witness review waits for a completed Maker run.", "WITNESS_NOT_READY", 409, false);
592:     }
593:     if (project.operations.some((operation) => ["QUEUED", "RUNNING", "WAITING_PERMISSION", "COMPLETED_UNAPPLIED", "ABANDONED"].includes(operation.status))) {
594:       throw new ExperienceFailure("An earlier native run is unresolved. Reconcile it before starting another.", "RUN_UNRESOLVED", 409, false);
595:     }
596:     const context = await this.modelContext(project);
597:     const startedAt = new Date().toISOString();
598:     const expectedOutput = intent === "clarify" ? "ORACLE_REPLY" : intent === "draft" ? "SECTION_DRAFT" : "WITNESS_REPLY";
599:     const sessionId = sessionFor(project, intent === "witness" ? "witness" : intent === "draft" ? "architect" : "oracle");
600:     const queued = await this.workflow.execute(actionId, payload, expectedRevision, (current) => {
601:       const next = structuredClone(current);
602:       next.engine = {
603:         model: context.model,
604:         source: context.source === "selected"
605:           ? current.engine.source
606:           : context.source === "legacy"
607:             ? "migrated-legacy"
608:             : context.source === "auto-discovery"
609:               ? "auto-discovery"
610:               : current.engine.source,
611:         updatedAt: startedAt,
612:         legacyModel: current.engine.legacyModel,
613:       };
614:       next.operations.push({
615:         id: randomUUID(),
616:         kind: intent === "witness" ? "witness" : "guide",
617:         payloadHash: payloadHash(payload),
618:         nativeSessionId: sessionId,
619:         nativeMessageId: null,
620:         status: "QUEUED",
621:         result: `Queued for OpenCode with ${context.model.providerID}/${context.model.id}${context.model.variant ? `#${context.model.variant}` : ""}.`,
622:         model: context.model,
623:         agent: context.roleAgents[intent === "witness" ? "witness" : intent === "draft" ? "architect" : "oracle"],
624:         startedAt,
625:         finishedAt: null,
626:         statusReason: null,
627:         lastObservedAt: null,
628:         appliedAt: null,
629:         providerError: null,
630:         intent,
631:         sectionId: intent === "draft" ? targetSection?.id ?? null : null,
632:         startingRevision: expectedRevision,
633:         idempotencyKey: actionId,
634:         expectedOutput,
635:         retryOf: null,
636:         progress: {
637:           phase: "CONNECTING",
638:           detail: PHASE_DETAIL.CONNECTING,
639:           updatedAt: startedAt,
640:         },
641:         oracleProceedWithAssumptions: intent === "clarify" && proceedWithAssumptions,
642:       });
643:       rememberTranscript(next, "user", this.redactPrompt(text));
644:       return refreshNextAction(next);
645:     });
646:     const operation = queued.project.operations.at(-1);
647:     if (!operation) throw new ExperienceFailure("The run was not recorded.", "RUN_NOT_RECORDED", 500, true);
648:     const role: "oracle" | "architect" | "maker" | "witness" = intent === "witness" ? "witness" : intent === "draft" ? "architect" : "oracle";
649:     try {
650:       const prompt = await this.instructions(role, queued.project, text, context.model, operation.sectionId);
651:       this.guides.start({
652:         operationId: operation.id,
653:         actionId,
654:         projectId: queued.project.id,
655:         intent,
656:         expectedOutput,
657:         sectionId: operation.sectionId,
658:         userText: text,
659:         sessionId,
660:         prompt,
661:         workspace: this.options.safeDirectory,
662:         model: context.model,
663:         agent: context.roleAgents[intent === "witness" ? "witness" : intent === "draft" ? "architect" : "oracle"],
664:         budget: queued.project.modelPreferences.budget,
665:       });
666:     } catch (error) {
667:       await this.guides.markFailed({
668:         operationId: operation.id,
669:         actionId,
670:         projectId: queued.project.id,
671:         intent,
672:         expectedOutput,
673:         sectionId: operation.sectionId,
674:         userText: text,
675:         sessionId,
676:         prompt: "",
