908:   private async claim(actionId: string, payload: object, expectedRevision: number): Promise<Claimed> {
909:     const loaded = await this.store.load();
910:     const hash = payloadHash(payload);
911:     const existing = loaded.state.actions.find((action) => action.id === actionId);
912:     if (existing) {
913:       if (existing.payloadHash !== hash) throw new RevisionConflict("Action ID was already used with a different payload.");
914:       return { project: loaded.state, duplicate: true };
915:     }
916:     if (loaded.state.revision !== expectedRevision) {
917:       throw new RevisionConflict(`Expected revision ${expectedRevision}, found ${loaded.state.revision}.`);
918:     }
919:     return { project: loaded.state, duplicate: false };
