125: 
126:   async sendMessage(
127:     actionId: string,
128:     expectedRevision: number,
129:     intent: "clarify" | "draft" | "question" | "witness",
130:     text: string,
131:     proceedWithAssumptions = false,
132:     sectionId: string | null = null,
133:   ) {
134:     const payload = { intent, text, proceedWithAssumptions, sectionId };
135:     const claimed = await this.claim(actionId, payload, expectedRevision);
136:     if (claimed.duplicate) return { project: claimed.project, duplicate: true };
137:     const project = claimed.project;
138:     try {
139:       if (intent === "clarify" || intent === "draft" || intent === "witness") {
140:         // Oracle, Architect, and Witness stage runs are persisted asynchronous
141:         // operations: the request returns as soon as the run is queued. The
142:         // `question` adapter stays synchronous because it changes no saved
143:         // state and answers directly.
144:         return await this.queueGuide(actionId, payload, expectedRevision, intent, text, project, proceedWithAssumptions, sectionId);
145:       }
146:       return await this.question(actionId, payload, expectedRevision, project, text);
147:     } catch (error) {
148:       if (error instanceof ExperienceFailure
149:         || error instanceof WorkflowConflict
150:         || error instanceof RevisionConflict
151:         || error instanceof StateError) throw error;
152:       return this.recordUncertain(actionId, payload, expectedRevision, intent, error);
153:     }
154:   }
