156:   async approve(actionId: string, expectedRevision: number, kind: "product" | "maker-scope", statement?: string) {
157:     const payload = { kind, statement: statement ?? null };
158:     return this.workflow.execute(actionId, payload, expectedRevision, (project) => {
159:       if (kind === "product") return approveProduct(project);
160:       return grantMakerScope(project, statement ?? "");
161:     });
162:   }
