164:   async runMaker(actionId: string, expectedRevision: number, retryOf: string | null = null) {
165:     const payload = { intent: "maker", retryOf };
166:     const claimed = await this.claim(actionId, payload, expectedRevision);
167:     if (claimed.duplicate) return { project: claimed.project, duplicate: true, accepted: false };
168:     const project = claimed.project;
169:     if (project.makerScope.status !== "GRANTED" || !project.makerScope.statement) {
170:       throw new ExperienceFailure("Grant a separate Maker scope before a native run.", "MAKER_SCOPE_REQUIRED", 409, false);
171:     }
172:     if (retryOf) {
173:       const source = project.operations.find((operation) => operation.id === retryOf);
174:       if (!source || source.kind !== "maker" || source.status !== "FAILED") {
175:         throw new ExperienceFailure(
176:           "A Maker run can be retried only after a confirmed failure of that same run. Reconcile uncertain runs first.",
177:           "RETRY_NOT_CONFIRMED",
178:           409,
179:           false,
180:         );
181:       }
182:     }
183:     if (project.operations.some((operation) => ["QUEUED", "RUNNING", "WAITING_PERMISSION", "COMPLETED_UNAPPLIED", "ABANDONED"].includes(operation.status))) {
184:       throw new ExperienceFailure("An earlier native run is unresolved. Reconcile it before starting another.", "RUN_UNRESOLVED", 409, false);
185:     }
186:     const makerScope = project.makerScope.statement;
187:     const context = await this.modelContext(project);
188:     const startedAt = new Date().toISOString();
189:     const queued = await this.workflow.execute(actionId, payload, expectedRevision, (current) => {
190:       const next = structuredClone(current);
191:       next.engine = {
192:         model: context.model,
193:         source: context.source === "selected"
194:           ? current.engine.source
195:           : context.source === "legacy"
196:             ? "migrated-legacy"
197:             : context.source === "auto-discovery"
198:               ? "auto-discovery"
199:               : current.engine.source,
200:         updatedAt: startedAt,
201:         legacyModel: current.engine.legacyModel,
202:       };
203:       next.operations.push({
204:         id: randomUUID(),
205:         kind: "maker",
206:         payloadHash: payloadHash(payload),
207:         nativeSessionId: sessionFor(next, "maker"),
208:         nativeMessageId: null,
209:         status: "QUEUED",
210:         result: `Queued for OpenCode with ${context.model.providerID}/${context.model.id}${context.model.variant ? `#${context.model.variant}` : ""}.`,
211:         model: context.model,
212:         agent: context.roleAgents.maker,
213:         startedAt,
214:         finishedAt: null,
215:         statusReason: null,
216:         lastObservedAt: null,
217:         appliedAt: null,
218:         providerError: null,
219:         intent: "maker-run",
220:         sectionId: null,
221:         startingRevision: expectedRevision,
222:         idempotencyKey: actionId,
223:         expectedOutput: "MAKER_DIFF",
224:         retryOf,
225:         progress: {
226:           phase: "CONNECTING",
227:           detail: PHASE_DETAIL.CONNECTING,
228:           updatedAt: startedAt,
229:         },
230:         oracleProceedWithAssumptions: false,
231:       });
232:       rememberTranscript(next, "user", retryOf
233:         ? this.redactPrompt(`Retried the Maker run after a confirmed failure.`)
234:         : this.redactPrompt(`Queued a Maker run with ${context.model.providerID}/${context.model.id}${context.model.variant ? `#${context.model.variant}` : ""}.`));
235:       return refreshNextAction(next);
236:     });
237:     const operation = queued.project.operations.at(-1);
238:     if (!operation) throw new ExperienceFailure("The Maker run was not recorded.", "RUN_NOT_RECORDED", 500, true);
239:     try {
240:       const prompt = await this.instructions("maker", queued.project, makerScope, context.model);
241:       this.runs.start({
242:         operationId: operation.id,
243:         projectId: queued.project.id,
244:         actionId,
245:         payload,
246:         sessionId: sessionFor(queued.project, "maker"),
247:         prompt,
248:         workspace: this.options.demoWorkspace,
249:         model: context.model,
250:         agent: context.roleAgents.maker,
251:         budget: queued.project.modelPreferences.budget,
252:       });
253:     } catch (error) {
254:       await this.runs.markFailed(operation.id, error, context.model, context.roleAgents.maker);
255:       throw error instanceof ExperienceFailure
256:         ? error
257:         : new ExperienceFailure(error instanceof Error ? this.redact(error.message) : "The Maker run could not start.", "RUN_START_FAILED", 500, true, operation.id);
258:     }
259:     return { project: queued.project, duplicate: false, accepted: true, operation };
260:   }
