262:   /** Retries a Maker run whose previous attempt failed with a confirmed outcome. */
263:   async retryRun(actionId: string, expectedRevision: number, operationId: string) {
264:     const project = await this.workflow.get();
265:     const operation = project.operations.find((item) => item.id === operationId);
266:     if (!operation) throw new WorkflowConflict("That operation is not in this project.");
267:     if (operation.kind !== "maker" || operation.status !== "FAILED") {
268:       throw new ExperienceFailure(
269:         "Retry after failure is available for a Maker run with a confirmed FAILED outcome. Uncertain runs must be reconciled first.",
270:         "RETRY_NOT_CONFIRMED",
271:         409,
272:         false,
273:         operationId,
274:       );
275:     }
276:     if (this.runs.active(operationId)) {
277:       throw new ExperienceFailure("That run is still active. Cancel it instead of retrying.", "RUN_STILL_ACTIVE", 409, false, operationId);
278:     }
279:     return this.runMaker(actionId, expectedRevision, operationId);
280:   }
281: 
282:   /** Marks a still-outstanding operation abandoned after the user confirms. */
283:   async abandonRun(actionId: string, expectedRevision: number, operationId: string) {
284:     const payload = { operationId, intent: "mark-abandoned" };
285:     const claimed = await this.claim(actionId, payload, expectedRevision);
286:     if (claimed.duplicate) return { project: claimed.project, duplicate: true };
287:     if (this.runs.active(operationId) || this.guides.active(operationId)) {
288:       throw new ExperienceFailure("An active in-process run must be cancelled instead of abandoned.", "RUN_STILL_ACTIVE", 409, false, operationId);
289:     }
290:     return this.workflow.execute(actionId, payload, expectedRevision, (project) => {
291:       const next = structuredClone(project);
292:       const operation = next.operations.find((item) => item.id === operationId);
293:       if (!operation) throw new WorkflowConflict("That operation is not in this project.");
294:       if (["SUCCEEDED", "FAILED", "CANCELLED", "ABANDONED"].includes(operation.status)) {
295:         throw new WorkflowConflict("A finished or already abandoned operation cannot be marked abandoned again.");
296:       }
297:       operation.status = "ABANDONED";
298:       operation.statusReason = "user-marked-abandoned";
299:       operation.finishedAt = new Date().toISOString();
300:       operation.lastObservedAt = operation.finishedAt;
301:       operation.result = `${operation.result ?? "The native run is outstanding."} Marked abandoned without a confirmed outcome; reconcile the native session if work must be recovered later.`;
302:       operation.progress = null;
303:       rememberTranscript(next, "system", operation.result);
304:       return refreshNextAction(next);
305:     });
306:   }
307: 
308:   async cancel(actionId: string, expectedRevision: number, operationId: string) {
309:     void expectedRevision;
310:     const active = this.runs.active(operationId) ?? this.guides.active(operationId);
311:     if (!active) {
312:       const project = (await this.store.load()).state;
313:       const operation = project.operations.find((item) => item.id === operationId);
314:       if (!operation) throw new WorkflowConflict("That operation is not in this project.");
315:       if (["SUCCEEDED", "FAILED", "CANCELLED", "COMPLETED_UNAPPLIED", "ABANDONED"].includes(operation.status)) {
316:         throw new WorkflowConflict("A finished or abandoned operation cannot be cancelled. Reconcile an abandoned operation instead.");
317:       }
318:       throw new ExperienceFailure("The in-process runner is no longer present. Reconcile the native session before taking another action.", "RUN_NOT_ACTIVE", 409, false, operationId);
319:     }
320:     let interrupted = false;
321:     const project = (await this.store.load()).state;
322:     const operation = project.operations.find((item) => item.id === operationId);
323:     if (active.sessionId && this.guide.interrupt) {
324:       try {
325:         interrupted = await this.guide.interrupt(active.sessionId);
326:       } catch (error) {
327:         throw new ExperienceFailure(
328:           `The native session could not be interrupted, so it was not marked cancelled: ${this.redact(error instanceof Error ? error.message : "unknown error")}`,
329:           "CANCEL_UNAVAILABLE",
330:           503,
331:           false,
332:           operationId,
333:         );
334:       }
335:     }
336:     if (operation?.kind === "maker") this.runs.markCancelled(operationId);
337:     else this.guides.markCancelled(operationId);
338:     return this.workflow.executeLatest(actionId, { operationId, intent: "cancel" }, (project) => {
339:       const next = structuredClone(project);
340:       const operation = next.operations.find((item) => item.id === operationId);
341:       if (!operation) throw new WorkflowConflict("That operation is not in this project.");
342:       if (["SUCCEEDED", "FAILED", "CANCELLED"].includes(operation.status)) {
343:         if (operation.status === "CANCELLED") return next;
344:         throw new WorkflowConflict("A finished operation cannot be cancelled.");
345:       }
346:       operation.status = "CANCELLED";
347:       operation.finishedAt = new Date().toISOString();
348:       operation.lastObservedAt = operation.finishedAt;
349:       operation.statusReason = "user-cancelled";
350:       operation.progress = null;
351:       operation.result = interrupted
352:         ? "Interrupted the native OpenCode session; the run was cancelled."
353:         : "Cancellation recorded. The native session was already idle or did not report an active request.";
354:       rememberTranscript(next, "system", operation.result);
355:       return refreshNextAction(next);
356:     });
357:   }
358: 
359:   /**
360:    * Reconciles an outstanding operation against its native session.
361:    *
362:    * The native outcome is observed, then the actual latest response or diff is
363:    * retrieved and validated before anything is applied. A validation pass marks
364:    * the operation once (appliedAt); repeated or duplicated reconcile actions
365:    * can never apply native work twice, and an idle session is never treated as
366:    * a successful run on its own.
367:    */
368:   async reconcile(actionId: string, expectedRevision: number, operationId: string) {
369:     const payload = { operationId, intent: "reconcile" };
370:     const claimed = await this.claim(actionId, payload, expectedRevision);
371:     if (claimed.duplicate) return { project: claimed.project, duplicate: true };
372:     const current = (await this.store.load()).state;
373:     const operation = current.operations.find((item) => item.id === operationId);
374:     if (!operation?.nativeSessionId) {
375:       throw new ExperienceFailure("This operation has no native session to reconcile.", "NOTHING_TO_RECONCILE", 409, false, operationId);
376:     }
377:     if (["SUCCEEDED", "FAILED", "CANCELLED"].includes(operation.status)) {
378:       throw new ExperienceFailure("A finished operation does not need reconciliation.", "ALREADY_FINISHED", 409, false, operationId);
379:     }
380:     const role = operation.kind === "maker"
381:       ? "maker"
382:       : operation.kind === "witness"
383:         ? "witness"
384:         : operation.intent === "clarify" ? "oracle" : "architect";
385:     const sessionId = operation.nativeSessionId;
386: 
387:     // A waiting permission stays waiting until OpenCode reports it resolved.
388:     if (operation.status === "WAITING_PERMISSION" || operation.status === "ABANDONED"
389:       || operation.progress?.phase === "WAITING_PERMISSION") {
390:       const pending = this.guide.hasPendingPermission
391:         ? await this.guide.hasPendingPermission(sessionId, operation.kind === "maker" ? this.options.demoWorkspace : this.options.safeDirectory)
392:         : null;
393:       if (pending === true) {
394:         return this.workflow.execute(actionId, payload, expectedRevision, (project) =>
395:           markPermissionStillPending(project, operationId));
396:       }
397:     }
398: 
399:     const observed = await this.guide.inspect(sessionId, {
400:       conversationId: current.id,
401:       role,
402:     });
403: 
404:     if (observed === "running") {
405:       return this.workflow.execute(actionId, payload, expectedRevision, (project) =>
406:         markRecovered(project, operationId, {
407:           status: "RUNNING",
408:           result: "The native session is still running. It was not started again; keep waiting or reconcile later.",
409:           sessionId,
410:           messageId: operation.nativeMessageId,
411:           diff: null,
412:           check: null,
413:           model: operation.model,
414:           phase: "RECEIVING_OUTPUT",
415:         }));
416:     }
417: 
418:     if (observed === "unknown" && operation.kind !== "maker") {
419:       // An unknown guide outcome stays reconcilable; nothing is invented here.
420:       return this.workflow.execute(actionId, payload, expectedRevision, (project) =>
421:         markRecoveredGuide(project, operationId, {
422:           status: "ABANDONED",
423:           result: "Native outcome is still unknown. This action was not repeated; reconcile again later or mark it abandoned.",
424:           statusReason: "native-outcome-unconfirmed",
425:           phase: "AWAITING_RECONCILIATION",
426:         }));
427:     }
428: 
429:     if (operation.kind === "maker") {
430:       // An idle Maker session is never success on its own: read the outcome
431:       // plus the actual recovered diff, then apply it exactly once.
432:       const diff = observed === "succeeded" && this.guide.sessionDiff
433:         ? await this.guide.sessionDiff(sessionId, this.options.demoWorkspace)
434:         : null;
435:       await applyRecoveredMakerResult(
436:         { workflow: this.workflow, demoWorkspace: this.options.demoWorkspace, nodeCheckTimeoutMs: this.budgets.nodeCheckTimeoutMs },
437:         {
438:           projectId: current.id,
439:           operationId,
440:           observed,
441:           diff,
442:           sessionId,
443:           messageId: operation.nativeMessageId,
444:           model: operation.model,
445:         },
446:       );
447:       const project = (await this.store.load()).state;
448:       return { project, duplicate: false };
449:     }
450: 
451:     // Guide operation: retrieve the actual late response before applying it.
452:     const snapshot = this.guide.lastAssistantText
453:       ? await this.guide.lastAssistantText(sessionId)
454:       : null;
455:     if (observed === "succeeded" && !snapshot) {
456:       return this.workflow.execute(actionId, payload, expectedRevision, (project) =>
457:         markRecoveredGuide(project, operationId, {
458:           status: "COMPLETED_UNAPPLIED",
459:           result: "The native session reported success, but the recovered reply could not be read yet. Reconcile again before any new run.",
460:           statusReason: "native-result-not-retrieved",
461:           phase: "AWAITING_RECONCILIATION",
462:         }));
463:     }
464:     if (observed === "failed") {
465:       return this.workflow.execute(actionId, payload, expectedRevision, (project) =>
466:         markRecoveredGuide(project, operationId, {
467:           status: "FAILED",
468:           result: "Reconciled from a failed or interrupted native session.",
469:           statusReason: "native-failure-confirmed",
470:           phase: null,
471:         }));
472:     }
473:     const intent = operation.intent === "clarify" || operation.intent === "draft" || operation.intent === "witness"
474:       ? operation.intent
475:       : null;
476:     if (!intent) {
477:       throw new ExperienceFailure(
478:         "This operation has no replayable guide action. Mark it abandoned and repeat the request.",
479:         "GUIDE_INTENT_UNKNOWN",
480:         409,
481:         false,
482:         operationId,
483:       );
484:     }
485:     const expected = readExpectedOutput(operation);
486:     if (expected === "QUESTION_REPLY" && observed === "succeeded") {
487:       // A question never mutates saved state; record the late confirmation.
488:       return this.workflow.execute(actionId, payload, expectedRevision, (project) =>
489:         markRecoveredGuide(project, operationId, {
490:           status: "SUCCEEDED",
491:           result: "Reconciled from the native session outcome.",
492:           statusReason: null,
493:           phase: null,
494:           messageId: snapshot?.messageId ?? null,
495:         }));
496:     }
497:     const reply = snapshot
498:       ? validateReply(intent, snapshot.text, (value) => this.redact(value))
499:       : { ok: false as const, resultText: "The recovered reply could not be read." };
500:     if (!reply.ok) {
501:       return this.workflow.execute(actionId, payload, expectedRevision, (project) =>
502:         markRecoveredGuide(project, operationId, {
503:           status: "FAILED",
504:           result: `The late ${spiritName(intent)} response does not match the expected format, so nothing was applied. Reply summary: ${reply.resultText.slice(0, 200)}`,
505:           statusReason: "malformed-response",
506:           phase: null,
507:           messageId: snapshot?.messageId ?? null,
508:         }));
509:     }
510:     let result;
511:     try {
512:       result = await this.workflow.execute(actionId, payload, expectedRevision, (project) =>
513:         applyValidatedReply(project, operationId, reply, {
514:           redact: (value) => this.redact(value),
515:           sessionId,
516:           messageId: snapshot?.messageId ?? null,
517:         }));
518:     } catch (error) {
519:       if (error instanceof SectionContractError) {
520:         return this.workflow.execute(actionId, payload, expectedRevision, (project) =>
521:           markRecoveredGuide(project, operationId, {
522:             status: "FAILED",
523:             result: `The late Architect candidate does not satisfy its content contract, so nothing was applied. ${error.message}`,
524:             statusReason: "contract-invalid",
525:             phase: null,
526:             messageId: snapshot?.messageId ?? null,
527:           }));
528:       }
529:       throw error;
530:     }
531:     const next = result.project;
532:     return { project: next, duplicate: result.duplicate };
533:   }
