34:   return `${model.providerID}/${model.id}${model.variant ? `#${model.variant}` : ""}`;
35: }
36: 
37: export function diffSummary(files: NativeFileDiff[]): string {
38:   return files
39:     .map((file) => `${file.status} ${file.file} (+${file.additions}/-${file.deletions})`)
40:     .join("\n");
41: }
42: 
43: function phaseValue(progress: OperationProgress | null, phase: OperationPhase, detail: string | null): OperationProgress {
44:   return setProgress(progress, phase, detail, new Date().toISOString());
45: }
46: 
47: /**
48:  * Owns the in-process half of a Maker run. Persisted operation state remains the
49:  * source of truth across process restarts; an interrupted process leaves a
50:  * reconcilable ABANDONED record rather than silently replaying the native action.
51:  */
52: export class MakerRunCoordinator {
53:   private readonly activeRuns = new Map<string, ActiveRun>();
54: 
55:   constructor(
56:     private readonly options: {
57:       workflow: WorkflowService;
58:       guide: SpiritGuide;
59:       demoWorkspace: string;
60:       nodeCheckTimeoutMs?: number;
61:     },
62:   ) {}
63: 
64:   start(input: MakerRunInput): void {
65:     if (this.activeRuns.has(input.operationId)) return;
66:     const active: ActiveRun = { sessionId: input.sessionId, cancelled: false };
67:     this.activeRuns.set(input.operationId, active);
68:     void this.execute(input, active)
69:       .catch(async (error) => {
70:         await this.markFailed(input.operationId, error, input.model, input.agent).catch(() => undefined);
71:       })
72:       .finally(() => {
73:         this.activeRuns.delete(input.operationId);
74:       });
75:   }
76: 
77:   active(operationId: string): { sessionId: string | null } | null {
78:     const found = this.activeRuns.get(operationId);
79:     return found ? { sessionId: found.sessionId } : null;
80:   }
81: 
82:   markCancelled(operationId: string): void {
83:     const found = this.activeRuns.get(operationId);
84:     if (found) found.cancelled = true;
85:   }
86: 
87:   async markFailed(operationId: string, error: unknown, model: ModelRef, agent: string | null): Promise<void> {
88:     const sessionId = typeof (error as { nativeSessionId?: unknown })?.nativeSessionId === "string"
89:       ? (error as { nativeSessionId: string }).nativeSessionId
90:       : null;
91:     const providerFailure = providerErrorFor(error, model.providerID, sessionId);
92:     const message = providerFailure?.whatHappened ?? (error instanceof Error ? error.message : "The Maker run could not start.");
93:     const uncertain = failureIsUncertain(message, error);
94:     await this.finish(operationId, {
95:       status: uncertain ? "ABANDONED" : "FAILED",
96:       result: message,
97:       model,
98:       agent,
99:       sessionId,
100:       diff: null,
101:       check: null,
102:       messageId: null,
103:       providerError: providerFailure,
104:       recovered: uncertain && sessionId ? "Reconcile the native session; a late result is applied exactly once." : undefined,
105:     });
106:   }
107: 
108:   private async execute(input: MakerRunInput, active: ActiveRun): Promise<void> {
109:     const startedAt = new Date().toISOString();
110:     const stage = async (state: OperationPhase, detail: string | null = null) => {
111:       await writeProgress(this.options.workflow, input.operationId, state, detail ?? PHASE_DETAIL[state]).catch(() => {
112:         // The terminal update retries against the latest revision; a failed
113:         // intermediate progress write never repeats native work.
114:       });
115:     };
116: 
117:     await this.update(input, "start", (project) => {
118:       const next = structuredClone(project);
119:       const operation = next.operations.find((item) => item.id === input.operationId);
120:       if (operation && operation.status === "QUEUED") {
121:         operation.status = "RUNNING";
122:         operation.startedAt ??= startedAt;
123:         operation.progress = phaseValue(operation.progress, "CONNECTING", PHASE_DETAIL.CONNECTING);
124:         operation.result = `Running in OpenCode with ${modelLabel(input.model)}.`;
125:       }
126:       return refreshNextAction(next);
127:     });
128: 
129:     let settled = false;
130:     const observation = this.observe(input, active, () => settled);
131:     try {
132:       const performed = await this.options.guide.perform({
133:         role: "maker",
134:         conversationId: input.projectId,
135:         sessionId: input.sessionId,
136:         prompt: input.prompt,
137:         workspace: input.workspace,
138:         model: input.model,
139:         agent: input.agent,
140:         budget: input.budget,
141:         onSession: (sessionId) => {
142:           active.sessionId = sessionId;
143:           void this.update(input, "session", (project) => {
144:             const next = structuredClone(project);
145:             const operation = next.operations.find((item) => item.id === input.operationId);
146:             if (operation) {
147:               operation.nativeSessionId = sessionId;
148:               operation.progress = phaseValue(operation.progress, "SESSION_CREATED", PHASE_DETAIL.SESSION_CREATED);
149:               operation.result = `Running in OpenCode session ${sessionId}.`;
150:             }
151:             rememberSession(next, "maker", sessionId);
152:             return refreshNextAction(next);
153:           }).catch(() => {
154:             // The completion update retries against the latest revision.
155:           });
156:         },
157:       });
158:       active.sessionId = performed.sessionId;
159:       settled = true;
160: 
161:       if (active.cancelled) {
162:         await this.finish(input.operationId, {
163:           status: "CANCELLED",
164:           result: "Cancellation was recorded before the native run finished.",
165:           model: input.model,
166:           agent: input.agent,
167:           sessionId: performed.sessionId,
168:           diff: performed.diff,
169:           messageId: performed.messageId,
170:           check: null,
171:           providerError: null,
172:         });
173:         return;
174:       }
175: 
176:       if (performed.pendingPermission) {
177:         await this.finish(input.operationId, {
178:           status: "WAITING_PERMISSION",
179:           result: "A native permission request is pending. Resolve it in OpenCode, then reconcile. The run was not repeated.",
180:           model: input.model,
181:           agent: input.agent,
182:           sessionId: performed.sessionId,
183:           diff: performed.diff,
184:           messageId: performed.messageId,
185:           check: null,
186:           providerError: null,
187:         });
188:         return;
189:       }
190: 
191:       const nativeFailed = performed.outcome === "failed" || performed.outcome === "interrupted";
192:       const stillRunning = performed.timedOut || performed.outcome === "running" || performed.outcome === "unknown";
193:       if (stillRunning) {
194:         await this.finish(input.operationId, {
195:           status: "ABANDONED",
196:           result: "The native Maker run did not become idle before the deadline. It was not repeated; reconcile before another run.",
197:           model: input.model,
198:           agent: input.agent,
199:           sessionId: performed.sessionId,
200:           diff: performed.diff,
201:           messageId: performed.messageId,
202:           check: null,
203:           providerError: null,
204:           recovered: "Reconcile the native session; a late result is applied exactly once.",
205:         });
206:         return;
207:       }
208: 
209:       const edited = !nativeFailed && !performed.diff.includes("without a file diff");
210:       let check: NodeCheck | null = null;
211:       if (edited) {
212:         await stage("RUNNING_CHECKS");
213:         check = await traceToolOperation("maker", input.projectId, input.model, "node.test", () =>
214:           runApprovedNodeCheck(this.options.demoWorkspace, this.options.nodeCheckTimeoutMs ?? 30_000));
215:       }
216:       await this.finish(input.operationId, {
217:         status: edited ? "SUCCEEDED" : "FAILED",
218:         result: performed.diff,
219:         model: input.model,
220:         agent: input.agent,
221:         sessionId: performed.sessionId,
222:         diff: performed.diff,
223:         messageId: performed.messageId,
224:         check,
225:         providerError: null,
226:       });
227:     } catch (error) {
228:       const message = error instanceof Error ? error.message : "The native Maker run failed.";
229:       const errorSessionId = typeof (error as { nativeSessionId?: unknown })?.nativeSessionId === "string"
230:         ? (error as { nativeSessionId: string }).nativeSessionId
231:         : null;
232:       const providerFailure = providerErrorFor(error, input.model.providerID, errorSessionId ?? active.sessionId);
233:       const safeMessage = providerFailure?.whatHappened ?? message;
234:       const uncertain = failureIsUncertain(safeMessage, error);
235:       await this.finish(input.operationId, {
236:         status: active.cancelled ? "CANCELLED" : uncertain ? "ABANDONED" : "FAILED",
237:         result: active.cancelled
238:           ? "Cancellation was recorded before the native run finished."
239:           : uncertain
240:             ? `Disconnected or interrupted: ${safeMessage}. Reconcile the native session before another run.`
241:             : safeMessage,
242:         model: input.model,
243:         agent: input.agent,
244:         sessionId: errorSessionId ?? active.sessionId,
245:         diff: null,
246:         messageId: null,
247:         check: null,
248:         providerError: providerFailure,
249:         recovered: uncertain ? "Reconcile the native session; a late result is applied exactly once." : undefined,
250:       });
251:     } finally {
252:       settled = true;
253:       void observation;
254:     }
255:   }
256: 
257:   /**
258:    * Safe polling while the native turn is in flight: it reports that model
259:    * output has started arriving without exposing any raw stream content.
260:    */
261:   private async observe(
262:     input: MakerRunInput,
263:     active: ActiveRun,
264:     finished: () => boolean,
265:   ): Promise<void> {
266:     const interval = 700;
267:     let waitingForModel = false;
268:     let observedOutput = false;
269:     while (!finished() && !active.cancelled) {
270:       const sessionId = active.sessionId;
271:       if (sessionId && !waitingForModel) {
272:         waitingForModel = true;
273:         await writeProgress(this.options.workflow, input.operationId, "WAITING_FOR_MODEL", PHASE_DETAIL.WAITING_FOR_MODEL).catch(() => undefined);
274:       }
275:       if (sessionId && this.options.guide.lastAssistantText && !observedOutput) {
276:         const snapshot = await this.options.guide.lastAssistantText(sessionId);
277:         if (snapshot && snapshot.text.trim()) {
278:           observedOutput = true;
279:           await writeProgress(this.options.workflow, input.operationId, "RECEIVING_OUTPUT", PHASE_DETAIL.RECEIVING_OUTPUT).catch(() => undefined);
280:         }
281:       }
282:       if (finished()) return;
283:       await new Promise((resolve) => setTimeout(resolve, interval));
284:     }
285:   }
286: 
287:   private async finish(
288:     operationId: string,
289:     outcome: {
290:       status: "SUCCEEDED" | "FAILED" | "CANCELLED" | "ABANDONED" | "WAITING_PERMISSION";
291:       result: string;
292:       model: ModelRef;
293:       agent: string | null;
294:       sessionId: string | null;
295:       diff: string | null;
296:       messageId: string | null;
297:       check: NodeCheck | null;
298:       providerError: ProviderErrorDetails | null;
299:       /** Optional recovery pointer appended when the outcome is still reconcilable. */
300:       recovered?: string;
301:     },
302:   ): Promise<void> {
303:     await this.options.workflow.executeLatest(`run:${operationId}:finish`, { operationId, status: outcome.status }, (project) => {
304:       const next = structuredClone(project);
305:       const operation = next.operations.find((item) => item.id === operationId);
306:       if (!operation) return refreshNextAction(next);
307:       if (operation.status === "CANCELLED") {
308:         operation.result = outcome.diff
309:           ? `Cancellation was recorded. Native result after cancellation: ${outcome.diff}`
310:           : operation.result;
311:         operation.finishedAt ??= new Date().toISOString();
312:         return refreshNextAction(next);
313:       }
314:       if (operation.appliedAt) {
315:         // The result was already applied by reconciliation; never replay it.
316:         return refreshNextAction(next);
317:       }
318:       operation.status = outcome.status;
319:       operation.model = outcome.model;
320:       operation.agent = outcome.agent;
321:       operation.nativeSessionId = outcome.sessionId ?? operation.nativeSessionId;
322:       operation.nativeMessageId = outcome.messageId ?? operation.nativeMessageId;
323:       operation.finishedAt = outcome.status === "WAITING_PERMISSION" || outcome.status === "ABANDONED"
324:         ? null
325:         : new Date().toISOString();
326:       operation.statusReason = outcome.providerError?.category.toLowerCase()
327:         ?? (outcome.status === "ABANDONED" ? "native-outcome-unconfirmed" : null);
328:       operation.lastObservedAt = new Date().toISOString();
329:       operation.appliedAt = outcome.status === "SUCCEEDED" ? operation.lastObservedAt : null;
330:       operation.providerError = outcome.providerError;
331:       const checkText = outcome.check
332:         ? `Node check exit ${outcome.check.code ?? "unavailable"}. ${outcome.check.output}`
333:         : "No native diff, so the Node check did not run.";
334:       operation.result = outcome.check ? `${outcome.result}\n\n${checkText}` : outcome.result;
335:       if (outcome.recovered) operation.result = `${operation.result} ${outcome.recovered}`;
336:       // Terminal operations carry the outcome in status/result; the transient
337:       // progress marker is cleared. A pending permission keeps its phase so
338:       // the interface explains why the run is still blocked, and an abandoned
339:       // run keeps its recovery marker so the native session remains
340:       // reconcileable after startup recovery.
341:       operation.progress = outcome.status === "WAITING_PERMISSION"
342:         ? phaseValue(operation.progress, "WAITING_PERMISSION", PHASE_DETAIL.WAITING_PERMISSION)
343:         : outcome.status === "ABANDONED" && operation.progress?.phase === "AWAITING_RECONCILIATION"
344:           ? operation.progress
345:           : null;
346:       if (outcome.sessionId) rememberSession(next, "maker", outcome.sessionId);
347:       if (outcome.check) {
348:         next.evidence.push({
349:           id: randomUUID(),
350:           checkId: "CK-06",
351:           nativeResultReference: outcome.sessionId ?? "native-session-unavailable",
352:           testedFingerprint: payloadHash(outcome.check.output),
353:           result: outcome.check.code === 0 ? "PASS" : "FAIL",
354:           observedAt: new Date().toISOString(),
355:           limitation: outcome.check.code === 0 ? null : "The native edit did not leave a passing Node test.",
356:           model: outcome.model,
357:         });
358:         const capability = next.capabilities.find((item) => item.id === "node-check");
359:         if (capability) {
360:           capability.availability = "available";
361:           capability.observedOutcome = outcome.check.code === 0 ? "PASS" : "FAIL";
362:         }
363:         const inspection = next.capabilities.find((item) => item.id === "inspect-changes");
364:         if (inspection) {
365:           inspection.availability = "available";
366:           inspection.observedOutcome = outcome.diff;
367:         }
368:       }
369:       rememberTranscript(
370:         next,
371:         "maker",
372:         outcome.status === "SUCCEEDED"
373:           ? `${outcome.diff ?? "Maker completed."} (${modelLabel(outcome.model)})`
374:           : `${outcome.result} (${modelLabel(outcome.model)})`,
375:       );
376:       return refreshNextAction(next);
377:     });
378:   }
379: 
380:   private async update(input: MakerRunInput, label: string, mutation: (project: Project) => Project): Promise<void> {
381:     await this.options.workflow.executeLatest(`run:${input.operationId}:${label}`, { operationId: input.operationId, label }, mutation);
382:   }
383: }
384: 
385: export interface RecoveredMakerResult {
386:   status: "SUCCEEDED" | "FAILED" | "COMPLETED_UNAPPLIED" | "RUNNING" | "ABANDONED";
387:   result: string;
388: }
389: 
390: /**
391:  * Applies a recovered Maker outcome to the persisted operation.
392:  *
393:  * `observed` comes from the live native session; the diff is retrieved fresh
394:  * from OpenCode and validated here, and the recovered result is recorded with
395:  * an exact-once guard (appliedAt) so repeated reconcile or retry actions never
396:  * duplicate native edits. An idle session without a confirmed outcome is
397:  * never treated as success.
398:  */
399: export async function applyRecoveredMakerResult(
400:   deps: { workflow: WorkflowService; demoWorkspace: string; nodeCheckTimeoutMs?: number },
401:   input: {
402:     projectId: string;
403:     operationId: string;
404:     observed: "running" | "succeeded" | "failed" | "unknown";
405:     diff: NativeFileDiff[] | null;
406:     sessionId: string | null;
407:     messageId: string | null;
408:     model: ModelRef | null;
409:   },
410: ): Promise<RecoveredMakerResult> {
411:   const apply = (mutation: Parameters<WorkflowService["executeLatest"]>[2]) =>
412:     deps.workflow.executeLatest(
413:       `run:${input.operationId}:reconcile:${randomUUID()}`,
414:       { operationId: input.operationId, observed: input.observed },
415:       mutation,
416:     );
417: 
418:   if (input.observed === "running") {
419:     await apply((project) => markRecovered(project, input.operationId, {
420:       status: "RUNNING",
421:       result: "Native session is still running. It was not started again; keep waiting or reconcile later.",
422:       sessionId: input.sessionId,
423:       messageId: input.messageId,
424:       diff: null,
425:       check: null,
426:       phase: "RECEIVING_OUTPUT",
427:       model: input.model,
428:     }));
429:     return { status: "RUNNING", result: "The native session is still running." };
430:   }
431: 
432:   if (input.observed === "unknown") {
433:     await apply((project) => markRecovered(project, input.operationId, {
434:       status: "ABANDONED",
435:       result: "Native outcome is still unknown. This action was not repeated; reconcile again later or mark it abandoned.",
436:       sessionId: input.sessionId,
437:       messageId: input.messageId,
438:       diff: null,
439:       check: null,
440:       phase: "AWAITING_RECONCILIATION",
441:       model: input.model,
442:       statusReason: "native-outcome-unconfirmed",
443:     }));
444:     return { status: "ABANDONED", result: "The native outcome is still unknown." };
445:   }
446: 
447:   if (input.observed === "failed") {
448:     await apply((project) => markRecovered(project, input.operationId, {
449:       status: "FAILED",
450:       result: "Reconciled from a failed or interrupted native session.",
451:       sessionId: input.sessionId,
452:       messageId: input.messageId,
453:       diff: null,
454:       check: null,
455:       statusReason: "native-failure-confirmed",
456:       model: input.model,
457:     }));
458:     return { status: "FAILED", result: "The native session reported a failed outcome." };
459:   }
460: 
461:   const diff = input.diff;
462:   if (diff === null) {
463:     await apply((project) => markRecovered(project, input.operationId, {
464:       status: "COMPLETED_UNAPPLIED",
465:       result: "The native session reported success, but the recovered diff could not be read yet. Reconcile again before any new run.",
466:       sessionId: input.sessionId,
467:       messageId: input.messageId,
468:       diff: null,
469:       check: null,
470:       phase: "AWAITING_RECONCILIATION",
471:       model: input.model,
472:       statusReason: "native-result-not-retrieved",
473:     }));
474:     return { status: "COMPLETED_UNAPPLIED", result: "The late diff could not be retrieved yet." };
475:   }
476: 
477:   if (diff.length === 0) {
478:     await apply((project) => markRecovered(project, input.operationId, {
479:       status: "FAILED",
480:       result: "Native session finished without a file diff.",
481:       sessionId: input.sessionId,
482:       messageId: input.messageId,
483:       diff: null,
484:       check: null,
485:       statusReason: "native-failure-confirmed",
486:       model: input.model,
487:     }));
488:     return { status: "FAILED", result: "The recovered session had no file diff." };
489:   }
490: 
491:   const check = await traceToolOperation("maker", input.projectId, input.model, "node.test", () =>
492:     runApprovedNodeCheck(deps.demoWorkspace, deps.nodeCheckTimeoutMs ?? 30_000));
493:   const summary = diffSummary(diff);
494:   await apply((project) => markRecovered(project, input.operationId, {
495:     status: "SUCCEEDED",
496:     result: `Reconciled from the native session outcome:\n${summary}`,
497:     sessionId: input.sessionId,
498:     messageId: input.messageId,
499:     diff: summary,
500:     check,
501:     model: input.model,
502:   }));
503:   return { status: "SUCCEEDED", result: `Late native result recovered:\n${summary}` };
504: }
505: 
506: export function markRecovered(
507:   project: Project,
508:   operationId: string,
509:   outcome: {
510:     status: "SUCCEEDED" | "FAILED" | "COMPLETED_UNAPPLIED" | "RUNNING" | "ABANDONED";
511:     result: string;
512:     sessionId: string | null;
513:     messageId: string | null;
514:     diff: string | null;
515:     check: NodeCheck | null;
516:     model: ModelRef | null;
517:     providerError?: ProviderErrorDetails | null;
518:     statusReason?: string | null;
519:     phase?: OperationPhase | null;
520:   },
521: ): Project {
522:   const next = structuredClone(project);
523:   const operation = next.operations.find((item) => item.id === operationId);
524:   if (!operation) return refreshNextAction(next);
525:   if (operation.appliedAt) {
526:     // A recovered result is applied exactly once; replays keep the record.
527:     return refreshNextAction(next);
528:   }
529:   if (operation.status === "CANCELLED") {
530:     operation.result = outcome.diff
531:       ? `Cancellation was recorded. Native result after cancellation: ${outcome.diff}`
532:       : operation.result;
533:     operation.finishedAt ??= new Date().toISOString();
534:     operation.progress = null;
535:     return refreshNextAction(next);
536:   }
537:   if (outcome.status === "SUCCEEDED") {
538:     if (!outcome.check) throw new Error("A recovered Maker success records a validated check result.");
539:     operation.status = "SUCCEEDED";
540:     const now = new Date().toISOString();
541:     operation.finishedAt ??= now;
542:     operation.appliedAt = now;
543:     operation.lastObservedAt = now;
544:     operation.nativeSessionId = outcome.sessionId ?? operation.nativeSessionId;
545:     operation.nativeMessageId = outcome.messageId ?? operation.nativeMessageId;
546:     operation.statusReason = null;
547:     operation.providerError = null;
548:     if (outcome.model) operation.model = outcome.model;
549:     const checkText = `Node check exit ${outcome.check.code ?? "unavailable"}. ${outcome.check.output}`;
550:     operation.result = `${outcome.result}\n${checkText}`;
551:     operation.progress = null;
552:     if (outcome.sessionId) rememberSession(next, "maker", outcome.sessionId);
553:     next.evidence.push({
554:       id: randomUUID(),
555:       checkId: "CK-06",
556:       nativeResultReference: outcome.sessionId ?? "native-session-unavailable",
557:       testedFingerprint: payloadHash(outcome.check.output),
558:       result: outcome.check.code === 0 ? "PASS" : "FAIL",
559:       observedAt: now,
560:       limitation: outcome.check.code === 0 ? null : "The native edit did not leave a passing Node test.",
561:       model: operation.model,
562:     });
563:     const capability = next.capabilities.find((item) => item.id === "node-check");
564:     if (capability) {
565:       capability.availability = "available";
566:       capability.observedOutcome = outcome.check.code === 0 ? "PASS" : "FAIL";
567:     }
568:     const inspection = next.capabilities.find((item) => item.id === "inspect-changes");
569:     if (inspection) {
570:       inspection.availability = "available";
571:       inspection.observedOutcome = outcome.diff;
572:     }
573:     rememberTranscript(
574:       next,
575:       "maker",
576:       `Reconciled the late native result: ${outcome.diff ?? outcome.result} (${modelLabel(outcome.model)})`,
577:     );
578:   } else {
579:     operation.status = outcome.status;
580:     const now = new Date().toISOString();
581:     operation.lastObservedAt = now;
582:     operation.statusReason = outcome.statusReason ?? null;
583:     operation.result = outcome.result;
584:     operation.providerError = outcome.providerError ?? null;
585:     operation.finishedAt = outcome.status === "FAILED" ? (operation.finishedAt ?? now) : null;
586:     if (outcome.model) operation.model = outcome.model;
587:     const phase: OperationPhase = outcome.phase
588:       ?? (outcome.status === "FAILED" ? "VALIDATING_RESULT" : "AWAITING_RECONCILIATION");
589:     operation.progress = operation.status === "FAILED"
590:       ? null
