354:       intake: Object.fromEntries(Object.entries(reply.reply.intake).map(([field, answer]) => [
355:         field,
356:         answer
357:           ? {
358:               ...answer,
359:               value: Array.isArray(answer.value)
360:                 ? answer.value.map(context.redact)
361:                 : context.redact(answer.value),
362:             }
363:           : null,
364:       ])) as typeof reply.reply.intake,
365:       proposal: reply.reply.proposal
366:         ? {
367:             ...reply.reply.proposal,
368:             title: context.redact(reply.reply.proposal.title),
369:             summary: context.redact(reply.reply.proposal.summary),
370:             intendedUser: context.redact(reply.reply.proposal.intendedUser),
371:             problem: context.redact(reply.reply.proposal.problem),
