430: function assertOracleReplyReady(
431:   project: Project,
432:   operation: Operation,
433:   reply: z.infer<typeof oracleReplySchema>,
434: ): void {
435:   if (reply.mode !== "proposal") return;
436:   const essential = [
437:     ["intendedUser", reply.intake.intendedUser],
438:     ["problem", reply.intake.problem],
439:     ["desiredOutcome", reply.intake.desiredOutcome],
440:     ["mustHaveFeatures", reply.intake.mustHaveFeatures?.value.length ? reply.intake.mustHaveFeatures : null],
441:   ] as const;
442:   const missing: string[] = essential.filter(([, answer]) => !answer).map(([field]) => field);
443:   if (project.source.status !== "CONFIRMED") missing.unshift("projectSource");
444:   if (missing.length) {
445:     throw new Error(`The Oracle proposed before required intake was consolidated: ${missing.join(", ")}.`);
446:   }
447:   const assumedEssential = essential
448:     .filter(([, answer]) => answer?.source === "ASSUMPTION")
449:     .map(([field]) => field);
450:   if (!assumedEssential.length) return;
451:   if (!operation.oracleProceedWithAssumptions) {
452:     throw new Error(`The Oracle proposed too early; explicit assumption permission is required for: ${assumedEssential.join(", ")}.`);
453:   }
454:   const assumed = new Set(reply.assumptions.map((assumption) => assumption.field));
455:   const uncovered = assumedEssential.filter((field) => !assumed.has(field));
456:   if (uncovered.length) {
457:     throw new Error(`The Oracle did not state assumptions for missing intake fields: ${uncovered.join(", ")}.`);
458:   }
459: }
