461: /**
462:  * Validates a reply for the expected output type. The same schemas and prose
463:  * fallbacks are used for live replies and late reconciliation, so a response
464:  * can never bypass validation.
465:  */
466: export function validateReply(
467:   intent: "clarify" | "draft" | "witness" | "question",
468:   text: string,
469:   redact: (value: string) => string,
470: ): ValidatedReply | { ok: false; resultText: string } {
471:   if (intent === "draft") {
472:     try {
473:       return { ok: true, intent: "draft", reply: sectionReplySchema.parse(extractJsonObject(text)) };
474:     } catch {
475:       const prose = text.trim();
476:       if (prose.length < 80) {
477:         return { ok: false, resultText: `The Architect reply was malformed, so the section was left unchanged. Reply began: ${redact(prose.slice(0, 240))}` };
478:       }
479:       return {
480:         ok: true,
481:         intent: "draft",
482:         reply: {
483:           content: prose.slice(0, 24_000),
484:           summary: "The Architect returned prose without a structured summary. Review the proposed revision before accepting it.",
485:           recommendation: "The Architect returned prose. Review the draft before approval.",
486:           tradeoff: "Separate recommendation and tradeoff fields were not returned.",
487:         },
488:       };
489:     }
490:   }
491:   if (intent === "witness") {
492:     try {
493:       return { ok: true, intent: "witness", reply: witnessReplySchema.parse(extractJsonObject(text)) };
494:     } catch {
495:       const prose = text.trim();
496:       if (prose.length < 80) {
497:         return { ok: false, resultText: `The Witness reply was malformed, so no draft was stored. Reply began: ${redact(prose.slice(0, 240))}` };
498:       }
499:       return {
500:         ok: true,
501:         intent: "witness",
502:         reply: {
503:           findings: prose.slice(0, 8_000),
504:           limitations: "The Witness returned prose rather than separate fields.",
505:           draftNotes: "These notes are an in-app review. They are not a submitted article or video.",
506:         },
507:       };
508:     }
509:   }
510:   try {
511:     return { ok: true, intent: "clarify", reply: oracleReplySchema.parse(extractJsonObject(text)) };
512:   } catch {
513:     return { ok: false, resultText: "The Oracle reply was malformed, so no proposal was stored." };
514:   }
515: }

