239: export interface ContractValidation {
240:   ok: boolean;
241:   errors: string[];
242:   satisfiedTopics: string[];
243:   missingTopics: string[];
244:   metrics: {
245:     headings: number;
246:     paragraphs: number;
247:     listItems: number;
248:     tableRows: number;
249:   };
250: }
251: 
252: function normalized(value: string): string {
253:   return value.toLowerCase().replace(/[’']/g, "").replace(/\s+/g, " ");
254: }
255: 
256: function sectionItems(blocks: MarkdownBlock[], aliases: string[]): string[] {
257:   const items: string[] = [];
258:   let activeLevel: number | null = null;
259:   for (const block of blocks) {
260:     if (block.type === "heading") {
261:       const heading = normalized(block.text);
262:       if (activeLevel !== null && block.level <= activeLevel) activeLevel = null;
263:       if (activeLevel === null && aliases.some((alias) => heading.includes(normalized(alias)))) {
264:         activeLevel = block.level;
265:       }
266:       continue;
267:     }
268:     if (activeLevel === null) continue;
269:     if (block.type === "list") items.push(...block.items.map((item) => item.text));
270:     else if (block.type === "table") items.push(...block.rows.flat());
271:     else if (block.type === "paragraph" || block.type === "blockquote") items.push(block.text);
272:   }
273:   return items.filter((item) => item.trim().length > 0);
274: }
