276: /**
277:  * Validates a generated section against its contract. Word count alone can
278:  * never pass: topics, block structure, dependency acknowledgement, and the
279:  * risk/decision/acceptance sections are checked independently.
280:  */
281: export function validateSectionContent(sectionId: string, content: string): ContractValidation {
282:   const contract = sectionContract(sectionId);
283:   if (!contract) {
284:     return {
285:       ok: false,
286:       errors: [`Unknown Architect section: ${sectionId}.`],
287:       satisfiedTopics: [],
288:       missingTopics: [],
289:       metrics: { headings: 0, paragraphs: 0, listItems: 0, tableRows: 0 },
290:     };
291:   }
292:   const blocks = parseMarkdown(content);
293:   const text = normalized(markdownPlainText(blocks));
294:   const metrics = {
295:     headings: blocks.filter((block) => block.type === "heading").length,
296:     paragraphs: blocks.filter((block) => block.type === "paragraph" && block.text.trim().length > 0).length,
297:     listItems: blocks.reduce((total, block) => total + (block.type === "list" ? block.items.length : 0), 0),
298:     tableRows: blocks.reduce((total, block) => total + (block.type === "table" ? block.rows.length : 0), 0),
299:   };
300:   const errors: string[] = [];
301:   const satisfiedTopics: string[] = [];
302:   const missingTopics: string[] = [];
303: 
304:   for (const topic of contract.requiredTopics) {
305:     const covered = topic.terms.some((term) => text.includes(normalized(term)));
306:     if (covered) satisfiedTopics.push(topic.id);
307:     else {
308:       missingTopics.push(topic.id);
309:       errors.push(`Missing required topic: ${topic.label}.`);
310:     }
311:   }
312: 
313:   if (metrics.headings < contract.requiredBlocks.headings) {
314:     errors.push(`Use at least ${contract.requiredBlocks.headings} headings so the section is scannable.`);
315:   }
316:   if (metrics.paragraphs < contract.requiredBlocks.paragraphs) {
317:     errors.push(`Use at least ${contract.requiredBlocks.paragraphs} substantive paragraphs.`);
318:   }
319:   if (metrics.listItems < contract.requiredBlocks.listItems) {
320:     errors.push(`Use at least ${contract.requiredBlocks.listItems} list or table items.`);
321:   }
322: 
323:   for (const requirement of contract.requiredHeadings) {
324:     const items = sectionItems(blocks, requirement.aliases);
325:     if (!items.length) errors.push(`Add a ${requirement.label} section with at least one item.`);
326:   }
327: 
328:   if (contract.requiresDependencySection && contract.dependencies.length) {
329:     const dependencyItems = sectionItems(blocks, dependencyHeading.aliases);
330:     if (!dependencyItems.length) {
331:       errors.push("Add a Dependencies section that names each upstream section.");
332:     } else {
333:       const dependencyText = normalized(dependencyItems.join(" "));
334:       for (const dependency of contract.dependencies) {
335:         const dependencyContract = sectionContract(dependency);
336:         const label = dependencyContract?.title.split(" ")[0] ?? dependency;
337:         if (!dependencyText.includes(normalized(label)) && !text.includes(normalized(label))) {
338:           errors.push(`Acknowledge the upstream ${label} section in Dependencies.`);
339:         }
340:       }
341:     }
342:   }
343: 
344:   return {
345:     ok: errors.length === 0,
346:     errors: [...new Set(errors)],
347:     satisfiedTopics,
348:     missingTopics,
349:     metrics,
350:   };
351: }
