353: /** Prompt-ready contract text. It is not a runtime system prompt. */
354: export function describeSectionContract(contract: SectionContract): string {
355:   return [
356:     `Section ${contract.title}`,
357:     `Purpose: ${contract.purpose}`,
358:     `Required topics: ${contract.requiredTopics.map((topic) => `${topic.label} (${topic.terms.join(", ")})`).join("; ")}.`,
359:     `Detail: ${contract.detailGuidance} Use at least ${contract.requiredBlocks.headings} headings, ${contract.requiredBlocks.paragraphs} paragraphs, and ${contract.requiredBlocks.listItems} list or table items.`,
360:     `Dependencies: ${contract.dependencies.length ? contract.dependencies.map((id) => sectionContract(id)?.title ?? id).join("; ") : "none"}.`,
361:     `Risks: ${contract.riskRequirements.join(" ")}`,
362:     `Decisions: ${contract.decisionRequirements.join(" ")}`,
363:     `Acceptance criteria: ${contract.acceptanceCriteria.join(" ")}`,
364:     `Required sections: ${contract.requiredHeadings.map((heading) => heading.label).join("; ")}.`,
365:   ].join("\n");
366: }

