import { z } from "zod";
import {
  TOOL_CATALOG,
  TOOL_CATALOG_MAX_AGE_DAYS,
  TOOL_CATALOG_VERIFIED_AT,
  TOOL_CATALOG_VERSION,
  TOOL_COST_LABELS,
  TOOL_EFFORT_LABELS,
  TOOL_NEED_LABELS,
  TOOL_STATUS_LABELS,
  catalogFreshness,
  toolNeedSchema,
  type ToolCatalogEntry,
  type ToolCostModel,
  type ToolNeed,
  type ToolStatus,
} from "./tool-catalog.ts";
import type { ToolDecision } from "./workflow.ts";

/**
 * Deterministic recommendation rules.
 *
 * The engine reads only the versioned catalog and structured project facts. It
 * never calls a model, network, installer, account API, or deployment target.
 * A recommendation is not an approval, install, purchase, or scope grant.
 */

export const recommendationConstraintsSchema = z.object({
  noSpend: z.boolean(),
  localOnly: z.boolean(),
  openSourceOnly: z.boolean(),
  privacySensitive: z.boolean(),
  hasHardware: z.boolean(),
  deadlineSoon: z.boolean(),
  existingStack: z.array(z.string().max(64)).max(30),
});
export type RecommendationConstraints = z.infer<typeof recommendationConstraintsSchema>;

export const recommendationContextSchema = z.object({
  idea: z.string(),
  needs: z.array(toolNeedSchema),
  constraints: recommendationConstraintsSchema,
});
export type RecommendationContext = z.infer<typeof recommendationContextSchema>;

export const toolRecommendationSchema = z.object({
  toolId: z.string(),
  name: z.string(),
  score: z.number().int(),
  status: z.enum(["CORE", "CONDITIONAL", "PROMO_ONLY", "EXCLUDED"]),
  statusLabel: z.string(),
  costModel: z.enum(["OPEN_SOURCE", "OPEN_WEIGHT", "SELF_HOSTED_FREE", "PROPRIETARY_FREE_TIER", "TRIAL_OR_PROMO", "PAID_OR_HARDWARE"]),
  costLabel: z.string(),
  costSummary: z.string(),
  why: z.string(),
  whyNot: z.string(),
  prerequisites: z.array(z.string()),
  effort: z.enum(["LOW", "MEDIUM", "HIGH"]),
  effortLabel: z.string(),
  limitations: z.array(z.string()),
  privacyNotes: z.string(),
  lockInNotes: z.string(),
  fallback: z.string(),
  challengeRelevance: z.string(),
  matchedNeeds: z.array(toolNeedSchema),
});
export type ToolRecommendation = z.infer<typeof toolRecommendationSchema>;

export const notRecommendedToolSchema = z.object({
  toolId: z.string(),
  name: z.string(),
  reason: z.string(),
});
export type NotRecommendedTool = z.infer<typeof notRecommendedToolSchema>;

export const recommendationResultSchema = z.object({
  catalogVersion: z.string(),
  catalogVerifiedAt: z.string(),
  maxAgeDays: z.number().int().positive(),
  ageDays: z.number().int().nonnegative(),
  stale: z.boolean(),
  needs: z.array(toolNeedSchema),
  constraints: recommendationConstraintsSchema,
  recommendations: z.array(toolRecommendationSchema),
  notRecommended: z.array(notRecommendedToolSchema),
});
export type RecommendationResult = z.infer<typeof recommendationResultSchema>;

export interface RecommendationProject {
  product: {
    status: string;
    proposal: string | null;
    structuredProposal?: {
      title?: string;
      summary?: string;
      problem?: string;
      desiredOutcome?: string;
      mustHaveFeatures?: string[];
      optionalFeatures?: string[];
      nonGoals?: string[];
      assumptions?: string[];
    } | null;
  };
  oracleIntake: {
    intendedUser?: { value: string } | null;
    problem?: { value: string } | null;
    desiredOutcome?: { value: string } | null;
    deadlineEvent?: { value: string } | null;
    mustHaveFeatures?: { value: string[] } | null;
    optionalFeatures?: { value: string[] } | null;
    budget?: { value: string } | null;
    privacyRequirements?: { value: string[] } | null;
    platforms?: { value: string[] } | null;
    nonGoals?: { value: string[] } | null;
