    access: { mode: string; dataPolicy: string };
    budget: { maxCostUsd: number | null };
  };
  memory?: {
    decisions?: Array<{ text: string; status?: string }>;
    constraints?: Array<{ text: string; status?: string }>;
  };
  toolDecisions?: ToolDecision[];
}

const NEED_PATTERNS: Record<ToolNeed, RegExp> = {
  web: /\b(?:web|website|frontend|front-end|react|browser app|web app|ui)\b/i,
  "ai-inference": /\b(?:ai|llm|language model|inference|generate|generation|chatbot|assistant|classif(?:y|ier))\b/i,
  "fine-tuning": /\b(?:fine[- ]?tun|train(?:ing)?|lora|adapter)\b/i,
