  hardware: /\b(?:arduino|sensor|hardware|microcontroller|iot|device|robot|electronics)\b/i,
  voice: /\b(?:voice|speech|tts|text[- ]to[- ]speech|audio|narration|spoken)\b/i,
  "browser-automation": /\b(?:browser automation|scrap(?:e|ing)|crawl(?:er|ing)?|selenium|playwright|stagehand|headless browser)\b/i,
  authentication: /\b(?:auth(?:entication|orization)?|login|log in|sign in|sign-in|identity|oauth|sso|session)\b/i,
  search: /\b(?:web search|search results|serp|lookup|search api)\b/i,
  "durable-workflows": /\b(?:durable workflow|background job|job queue|queue|retryable workflow|temporal|orchestration)\b/i,
  "time-series": /\b(?:time[- ]series|timeseries|metrics|telemetry|analytics|monitoring|sensor history)\b/i,
  "remote-database": /\b(?:database|db|persist(?:ence|ent)?|storage|mongodb|postgres|sqlite|data store)\b/i,
  "vector-search": /\b(?:vector|embedding|semantic search|similarity search|rag|retrieval)\b/i,
