  "agent-tooling": /\b(?:agent framework|agent tooling|multi-agent|agent orchestration|backboard|mastra)\b/i,
  "development-evidence": /\b(?:development evidence|session capture|checkpoint|entire|audit trail)\b/i,
  "local-runtime": /\b(?:linux|operating system|os|local runtime|offline runtime|workstation)\b/i,
};

const STACK_HINTS: Array<{ token: string; tools: string[] }> = [
  { token: "react", tools: ["playwright"] },
  { token: "typescript", tools: ["playwright", "mastra"] },
  { token: "node", tools: ["sqlite", "playwright", "render"] },
  { token: "python", tools: ["tabpfn", "ollama"] },
  { token: "sqlite", tools: ["sqlite"] },
  { token: "postgres", tools: ["tiger-data"] },
  { token: "mongodb", tools: ["mongodb-atlas"] },
  { token: "tailwind", tools: ["playwright"] },
  { token: "playwright", tools: ["playwright"] },
  { token: "gemma", tools: ["gemma", "ollama"] },
  { token: "arduino", tools: ["arduino"] },
];

function uniqueNeeds(values: ToolNeed[]): ToolNeed[] {
  const seen = new Set<ToolNeed>();
  const result: ToolNeed[] = [];
  for (const value of values) {
    if (seen.has(value)) continue;
    seen.add(value);
    result.push(value);
  }
  return result;
}

/** Derives structured needs from fixed vocabulary patterns, never from a model. */
export function deriveToolNeeds(text: string): ToolNeed[] {
  return uniqueNeeds((Object.keys(NEED_PATTERNS) as ToolNeed[]).filter((need) => NEED_PATTERNS[need].test(text)));
}

function projectText(project: RecommendationProject): string {
  const proposal = project.product.structuredProposal ?? null;
  const intake = project.oracleIntake;
  return [
    project.product.proposal,
    proposal?.title,
    proposal?.summary,
    proposal?.problem,
    proposal?.desiredOutcome,
    ...(proposal?.mustHaveFeatures ?? []),
    ...(proposal?.optionalFeatures ?? []),
    ...(proposal?.nonGoals ?? []),
    ...(proposal?.assumptions ?? []),
    intake.intendedUser?.value,
    intake.problem?.value,
    intake.desiredOutcome?.value,
    ...(intake.mustHaveFeatures?.value ?? []),
    ...(intake.optionalFeatures?.value ?? []),
    ...(intake.platforms?.value ?? []),
    ...(intake.nonGoals?.value ?? []),
    ...intake.knownConstraints,
    ...(intake.assumptions ?? []).map((assumption) => assumption.statement),
    ...(project.memory?.decisions ?? []).filter((entry) => entry.status !== "SUPERSEDED").map((entry) => entry.text),
    ...(project.memory?.constraints ?? []).filter((entry) => entry.status !== "SUPERSEDED").map((entry) => entry.text),
  ].filter((value): value is string => typeof value === "string" && value.trim().length > 0).join("\n");
}

function existingStack(text: string): string[] {
  const lower = text.toLowerCase();
  return STACK_HINTS.map((hint) => hint.token).filter((token) => lower.includes(token));
}

/**
 * Builds a recommendation context from persisted project facts. It does not
 * read the workspace path, credentials, raw prompts, or provider responses.
 */
export function recommendationContextFromProject(project: RecommendationProject): RecommendationContext {
  const text = projectText(project);
  const intake = project.oracleIntake;
  const budgetText = [
    intake.budget?.value,
    ...intake.knownConstraints,
    ...(intake.nonGoals?.value ?? []),
  ].filter(Boolean).join(" ");
  const deadlineText = [intake.deadlineEvent?.value, ...intake.knownConstraints].filter(Boolean).join(" ");
  const privacyText = (intake.privacyRequirements?.value ?? []).join(" ");
  const constraints: RecommendationConstraints = {
    noSpend: /(?:\bno|\bzero|\bwithout)\s+(?:spend|spending|budget|cost|money|payment)|\$0\b|free[- ]only|no paid/i.test(budgetText),
    localOnly: /\b(?:local[- ]only|offline|on[- ]device|no cloud|without (?:a )?(?:cloud|hosted service)|self[- ]host(?:ed)? only)\b/i.test(text)
      || project.modelPreferences.access.mode === "FREE_OR_LOCAL_ONLY",
    openSourceOnly: /\b(?:open[- ]source only|oss only|only open[- ]source)\b/i.test(text),
    privacySensitive: privacyText.trim().length > 0 || project.modelPreferences.access.dataPolicy === "NO_TRAINING_REQUIRED",
    hasHardware: /\b(?:i (?:already )?(?:have|own)|already (?:have|own)|available (?:hardware|board)|on my desk)\b[^.]{0,80}\b(?:arduino|board|sensor|hardware)\b|\b(?:arduino|board|sensor|hardware)\b[^.]{0,80}\b(?:available|owned|already have)\b/i.test(text),
    deadlineSoon: /\b(?:today|tomorrow|tonight|this week|next \d+ hours|\d+ hours|48 hours|urgent|last minute)\b/i.test(deadlineText),
    existingStack: existingStack(text),
  };
  return { idea: text, needs: deriveToolNeeds(text), constraints };
}

function evaluate(
  entry: ToolCatalogEntry,
  needs: ToolNeed[],
  constraints: RecommendationConstraints,
): { ok: true; matchedNeeds: ToolNeed[] } | { ok: false; reason: string } {
  if (entry.harnessAlternative) {
    return { ok: false, reason: "Coding harnesses are not recommended by this workshop. OpenCode remains the only harness." };
  }
  if (entry.status === "EXCLUDED") {
    return { ok: false, reason: entry.exclusionReason ?? "This tool is excluded from the current product." };
  }
  const matchedNeeds = entry.needs.filter((need) => needs.includes(need));
  if (matchedNeeds.length === 0) {
    return { ok: false, reason: "No matching project need was detected." };
  }
  if (constraints.noSpend) {
    const ownedHardware = constraints.hasHardware && entry.setupModes.includes("HARDWARE");
    if (entry.costModel === "TRIAL_OR_PROMO") {
      return { ok: false, reason: "Excluded by the no-spend constraint: promotional credit is not permanent free usage." };
    }
    if (entry.costModel === "PAID_OR_HARDWARE" && !ownedHardware) {
      return { ok: false, reason: "Excluded by the no-spend constraint: it requires a purchase or hardware." };
    }
  }
  if (constraints.localOnly && entry.hosting === "HOSTED") {
    return { ok: false, reason: "Requires a hosted service; the project is local-only." };
  }
  if (constraints.openSourceOnly
    && entry.costModel !== "OPEN_SOURCE"
    && entry.costModel !== "OPEN_WEIGHT"
    && entry.costModel !== "SELF_HOSTED_FREE") {
    return { ok: false, reason: "Excluded by the open-source-only constraint." };
  }
  if (constraints.privacySensitive
    && (entry.dataHandling === "HOSTED_PROCESSES_DATA" || entry.dataHandling === "UNKNOWN")) {
    return { ok: false, reason: "Processes project data on a hosted service; excluded by the privacy constraint." };
  }
  if (!constraints.hasHardware && entry.setupModes.includes("HARDWARE")) {
    return { ok: false, reason: "Requires physical hardware that is not available." };
  }
  if (constraints.deadlineSoon && entry.effort === "HIGH") {
    return { ok: false, reason: "High integration effort is a poor fit for the stated deadline." };
  }
  return { ok: true, matchedNeeds };
}

function score(entry: ToolCatalogEntry, matchedNeeds: ToolNeed[], constraints: RecommendationConstraints): number {
  let value = matchedNeeds.length * 10;
  if (entry.status === "CORE") value += 4;
  else if (entry.status === "CONDITIONAL") value += 2;
  else if (entry.status === "PROMO_ONLY") value += 1;
  if (entry.effort === "LOW") value += 3;
  else if (entry.effort === "MEDIUM") value += 1;
  if (constraints.deadlineSoon && entry.effort === "LOW") value += 4;
  if (constraints.privacySensitive && (entry.dataHandling === "LOCAL_ONLY" || entry.dataHandling === "SELF_HOST")) value += 3;
  if (constraints.localOnly && (entry.hosting === "LOCAL" || entry.hosting === "EITHER")) value += 2;
  if (entry.costModel === "OPEN_SOURCE" || entry.costModel === "OPEN_WEIGHT" || entry.costModel === "SELF_HOSTED_FREE") value += 1;
  if (constraints.existingStack.some((stack) => entry.id.includes(stack) || entry.name.toLowerCase().includes(stack))) value += 4;
  return value;
}

function recommendationFor(
  entry: ToolCatalogEntry,
  matchedNeeds: ToolNeed[],
  scoreValue: number,
): ToolRecommendation {
  const needLabels = matchedNeeds.map((need) => TOOL_NEED_LABELS[need]);
  return {
    toolId: entry.id,
    name: entry.name,
    score: scoreValue,
    status: entry.status,
    statusLabel: TOOL_STATUS_LABELS[entry.status],
    costModel: entry.costModel,
    costLabel: TOOL_COST_LABELS[entry.costModel],
    costSummary: `${TOOL_COST_LABELS[entry.costModel]}. ${entry.costNotes}`,
    why: `Matches ${needLabels.join(", ")}. ${entry.summary}`,
    whyNot: entry.cautions[0] ?? "No blocking caution was recorded; verify current terms before adopting.",
    prerequisites: [...entry.prerequisites],
    effort: entry.effort,
    effortLabel: TOOL_EFFORT_LABELS[entry.effort],
    limitations: [...entry.materialLimits],
    privacyNotes: entry.privacyNotes,
    lockInNotes: entry.lockInNotes,
    fallback: entry.fallback,
    challengeRelevance: entry.challengeRelevance,
    matchedNeeds,
  };
}

export interface RecommendationInput {
  idea: string;
  needs?: ToolNeed[];
  constraints?: Partial<RecommendationConstraints>;
  now?: Date | string;
  limit?: number;
}

/**
 * Returns a small, stable, ranked set. It never invents a commercial fact and
 * never includes a coding-harness alternative.
 */
export function recommendTools(input: RecommendationInput): RecommendationResult {
  const needs = uniqueNeeds(input.needs ?? deriveToolNeeds(input.idea));
  const constraints: RecommendationConstraints = {
    noSpend: false,
    localOnly: false,
    openSourceOnly: false,
    privacySensitive: false,
    hasHardware: false,
    deadlineSoon: false,
    existingStack: [],
    ...input.constraints,
  };
  const freshness = catalogFreshness(input.now);
  const candidates: Array<{ entry: ToolCatalogEntry; matchedNeeds: ToolNeed[]; score: number }> = [];
  const notRecommended = new Map<string, NotRecommendedTool>();

  for (const entry of TOOL_CATALOG) {
    const evaluated = evaluate(entry, needs, constraints);
    if (!evaluated.ok) {
      notRecommended.set(entry.id, { toolId: entry.id, name: entry.name, reason: evaluated.reason });
      continue;
    }
    candidates.push({
      entry,
      matchedNeeds: evaluated.matchedNeeds,
      score: score(entry, evaluated.matchedNeeds, constraints),
    });
  }

  candidates.sort((left, right) => right.score - left.score || left.entry.id.localeCompare(right.entry.id));
  const limit = Math.max(1, Math.min(input.limit ?? 5, 10));
  const selected: typeof candidates = [];
  const groups = new Set<string>();
  for (const candidate of candidates) {
    if (candidate.entry.exclusiveGroup && groups.has(candidate.entry.exclusiveGroup)) {
      notRecommended.set(candidate.entry.id, {
        toolId: candidate.entry.id,
        name: candidate.entry.name,
        reason: "Another tool in the same category ranked higher for these constraints.",
      });
      continue;
    }
    if (selected.length >= limit) {
      notRecommended.set(candidate.entry.id, {
        toolId: candidate.entry.id,
        name: candidate.entry.name,
        reason: "Lower-ranked than the small recommendation set.",
      });
      continue;
    }
    if (candidate.entry.exclusiveGroup) groups.add(candidate.entry.exclusiveGroup);
    selected.push(candidate);
  }

  return {
    catalogVersion: TOOL_CATALOG_VERSION,
    catalogVerifiedAt: TOOL_CATALOG_VERIFIED_AT,
    maxAgeDays: TOOL_CATALOG_MAX_AGE_DAYS,
    ageDays: freshness.ageDays,
    stale: freshness.stale,
    needs,
    constraints,
    recommendations: selected.map((candidate) => recommendationFor(candidate.entry, candidate.matchedNeeds, candidate.score)),
    notRecommended: [...notRecommended.values()].sort((left, right) => left.toolId.localeCompare(right.toolId)),
  };
}

/** Latest decision per tool, newest decision wins. */
export function latestToolDecision(project: { toolDecisions?: ToolDecision[] }, toolId: string): ToolDecision | null {
  return [...(project.toolDecisions ?? [])].reverse().find((decision) => decision.toolId === toolId) ?? null;
}

export function latestToolDecisions(project: { toolDecisions?: ToolDecision[] }): ToolDecision[] {
  const latest = new Map<string, ToolDecision>();
  for (const decision of project.toolDecisions ?? []) latest.set(decision.toolId, decision);
  return [...latest.values()].sort((left, right) => left.toolId.localeCompare(right.toolId));
}

