}) {
  const [kind, setKind] = useState<"NEW_PROJECT" | "LOCAL_REPOSITORY" | "REMOTE_REPOSITORY" | "SAVED_PROJECT">("NEW_PROJECT");
  const [value, setValue] = useState("");
