.engine-panel .meta { margin-top: var(--space-2); }
.engine-panel .button-link { margin-top: var(--space-1); color: var(--amber-bright); }

/* Focused workshop layout */
.compact-titlebar {
  align-items: center;
  min-height: 0;
  padding: var(--space-3) var(--space-1);
}
.workshop-title-actions { display: flex; align-items: center; gap: var(--space-3); }
.header-model-inline {
  max-width: 22ch;
  overflow: hidden;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.header-controls { gap: var(--space-2); white-space: nowrap; }
.header-controls:focus-visible { outline: 2px solid var(--amber); outline-offset: 3px; border-radius: var(--radius-sm); }

.workshop-drawer {
  margin-top: var(--space-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: linear-gradient(180deg, rgb(20 28 47 / 58%), rgb(9 13 23 / 78%));
  box-shadow: var(--shadow-1);
}
.workshop-drawer > summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  min-height: 48px;
  padding: var(--space-2) var(--space-4);
  color: var(--paper-soft);
  font-weight: 600;
  cursor: pointer;
  list-style: none;
}
.workshop-drawer > summary::-webkit-details-marker { display: none; }
.workshop-drawer > summary > span:first-child { display: inline-flex; align-items: center; gap: var(--space-2); min-width: 0; }
.workshop-drawer > summary:hover { color: var(--paper); background: rgb(240 235 225 / 3%); }
