+  cursor: pointer;
+  list-style: none;
+}
+.workshop-drawer > summary::-webkit-details-marker { display: none; }
+.workshop-drawer > summary > span:first-child { display: inline-flex; align-items: center; gap: var(--space-2); min-width: 0; }
+.workshop-drawer > summary:hover { color: var(--paper); background: rgb(240 235 225 / 3%); }
+.workshop-drawer > summary:focus-visible { outline: 2px solid var(--amber); outline-offset: -2px; border-radius: var(--radius-md); }
+.workshop-drawer[open] > summary { border-bottom: 1px solid var(--border); }
+.workshop-drawer-body { padding: var(--space-3) var(--space-4) var(--space-4); }
+.outline-drawer .section-list { grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }
+.outline-drawer .progress-track { margin-top: 0; }
+
+.focused-document {
