+  border-radius: var(--radius-sm);
+  background: rgb(5 7 13 / 34%);
+}
+.technical-details summary { color: var(--text-muted); font-family: var(--font-mono); font-size: 0.72rem; letter-spacing: 0.06em; text-transform: uppercase; cursor: pointer; }
