+.technical-list li { display: grid; gap: 1px; padding: var(--space-2); border: 1px solid var(--border); border-radius: var(--radius-sm); color: var(--text-dim); font-family: var(--font-mono); font-size: 0.68rem; overflow-wrap: anywhere; }
+.technical-list strong { color: var(--text-muted); }
+
+.project-memory { display: grid; gap: var(--space-4); }
+.memory-groups { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-3); }
+.memory-group { min-width: 0; padding: var(--space-3); border: 1px solid var(--border); border-radius: var(--radius-sm); background: rgb(5 7 13 / 28%); }
+.memory-group h3 { color: var(--paper-soft); font-size: 0.92rem; }
