+.memory-list li { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-2); padding-bottom: var(--space-2); border-bottom: 1px dashed var(--border); }
+.memory-list li:last-child { padding-bottom: 0; border-bottom: 0; }
+.memory-list li > div { min-width: 0; }
+.memory-list p { color: var(--text-muted); font-size: 0.82rem; overflow-wrap: anywhere; }
+.memory-field { display: inline-block; margin-bottom: 2px; color: var(--violet); font-family: var(--font-mono); font-size: 0.62rem; letter-spacing: 0.06em; text-transform: uppercase; }
+.memory-correct { min-height: 36px; flex: none; font-size: 0.72rem; }
